C
C Generated TIMESTAMP by SD/FAST, Kane's formulation
C (sdfast 2.0 #10001)
C
C
C ROADMAP (sphere.sd)
C
C Bodies           Inb
C No  Name         body Joint type  Coords q         Multipliers
C --- ------------ ---- ----------- ---------------- -----------------------
C   0 $ground                                       |
C   1 lat_and_long   0  U-joint       1   2         |
C   2 radius         1  Sliding       3?            |  1p
C   3 inner          2  Ball          4   5   6   7 |
C
C User Constraints
C
C   1 slipx                                         |  2
C   2 slipz                                         |  3
C
C
      BLOCK DATA SDBLKDATA
      INTEGER GROUND,NBOD,NDOF,NCONS,NLOOP,NLDOF,NLOOPC,NBALL,NLBALL,
     & NPRES,NUSER
      INTEGER JTYPE(3),INB(3),OUTB(3),NJNTDOF(3),NJNTC(3),NJNTP(3),
     & FIRSTQ(3),BALLQ(3),FIRSTM(3),FIRSTP(3)
      INTEGER TRANS(6),FIRSTU(2)
      COMMON/SDGTOPO/ GROUND,NBOD,NDOF,NCONS,NLOOP,NLDOF,NLOOPC,NBALL,
     & NLBALL,NPRES,NUSER,JTYPE,INB,OUTB,NJNTDOF,NJNTC,NJNTP,FIRSTQ,
     & BALLQ,FIRSTM,FIRSTP,TRANS,FIRSTU
      DOUBLE PRECISION GRAV(3),MK(3),IK(3,3,3),PIN(6,3)
      DOUBLE PRECISION RK(3,3),RI(3,3),PRES(6),STABVEL,STABPOS
      INTEGER MFRCFLG,ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,
     & LTAUFLG,FS0FLG,II,MMAP(6)
      INTEGER GRAVQ(3),MKQ(3),IKQ(3,3,3),PINQ(6,3),RKQ(3,3),RIQ(3,3),
     & PRESQ(6),STABVELQ,STABPOSQ
      DOUBLE PRECISION MTOT,PSMKG,RHEAD(3,3),RCOM(3,3),MKRCOMT(3,3,3),
     & PSIKG(3,3),PSRCOMG(3),PSRKG(3),PSRIG(3),PSMK(6),PSIK(6,3,3),
     & PSRCOM(6,3),PSRK(6,3),PSRI(6,3)
      COMMON/SDGINPUT/ GRAV,MK,IK,PIN,RK,RI,PRES,STABVEL,STABPOS,RHEAD,
     & RCOM,PSRCOMG,PSRCOM,MKRCOMT,PSMK,PSIK,PSRK,PSRI,PSMKG,PSIKG,PSRKG
     & ,PSRIG,MTOT,MFRCFLG,ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,
     & LTAUFLG,FS0FLG,II,MMAP,GRAVQ,MKQ,IKQ,PINQ,RKQ,RIQ,PRESQ,STABVELQ,
     & STABPOSQ
C  Topological information
C
      DATA GROUND/1/
      DATA NBOD/3/
      DATA NDOF/6/
      DATA NCONS/3/
      DATA NLOOP/0/
      DATA NLDOF/0/
      DATA NLOOPC/0/
      DATA NBALL/1/
