      DATA FIRSTU(1)/2/
      DATA FIRSTU(2)/3/
C Model parameters from the input file
C
C gravity
      DATA GRAV(1)/0D0/
      DATA GRAV(2)/-9.8D0/
      DATA GRAV(3)/0D0/
C
C mass
      DATA MK(1)/0D0/
      DATA MK(2)/0D0/
      DATA MK(3)/1D0/
C
C inertia
      DATA IK(1,1,1)/0D0/
      DATA IK(1,1,2)/0D0/
      DATA IK(1,1,3)/0D0/
      DATA IK(1,2,1)/0D0/
      DATA IK(1,2,2)/0D0/
