      DATA IK(1,3,2)/0D0/
      DATA IK(1,3,3)/0D0/
      DATA IK(2,1,1)/0D0/
      DATA IK(2,1,2)/0D0/
      DATA IK(2,1,3)/0D0/
      DATA IK(2,2,1)/0D0/
      DATA IK(2,2,2)/0D0/
      DATA IK(2,2,3)/0D0/
      DATA IK(2,3,1)/0D0/
      DATA IK(2,3,2)/0D0/
      DATA IK(2,3,3)/0D0/
      DATA IK(3,1,1)/.4D0/
      DATA IK(3,1,2)/0D0/
      DATA IK(3,1,3)/0D0/
      DATA IK(3,2,1)/0D0/
      DATA IK(3,2,2)/.4D0/
      DATA IK(3,2,3)/0D0/
      DATA IK(3,3,1)/0D0/
      DATA IK(3,3,2)/0D0/
      DATA IK(3,3,3)/.4D0/
C
C tree hinge axis vectors
      DATA PIN(1,1)/0D0/
      DATA PIN(1,2)/1D0/
      DATA PIN(1,3)/0D0/
      DATA PIN(2,1)/1D0/
      DATA PIN(2,2)/0D0/
      DATA PIN(2,3)/0D0/
      DATA PIN(3,1)/0D0/
      DATA PIN(3,2)/1D0/
      DATA PIN(3,3)/0D0/
      DATA PIN(4,1)/0D0/
      DATA PIN(4,2)/0D0/
      DATA PIN(4,3)/0D0/
      DATA PIN(5,1)/0D0/
      DATA PIN(5,2)/0D0/
      DATA PIN(5,3)/0D0/
      DATA PIN(6,1)/0D0/
      DATA PIN(6,2)/0D0/
      DATA PIN(6,3)/0D0/
C
C tree bodytojoint vectors
      DATA RK(1,1)/0D0/
      DATA RK(1,2)/0D0/
      DATA RK(1,3)/0D0/
      DATA RK(2,1)/0D0/
      DATA RK(2,2)/0D0/
