      DATA RK(3,1)/0D0/
      DATA RK(3,2)/0D0/
      DATA RK(3,3)/0D0/
C
C tree inbtojoint vectors
      DATA RI(1,1)/0D0/
      DATA RI(1,2)/0D0/
      DATA RI(1,3)/0D0/
      DATA RI(2,1)/0D0/
      DATA RI(2,2)/0D0/
