      DATA PRES(4)/0D0/
      DATA PRES(5)/0D0/
      DATA PRES(6)/0D0/
C
C stabilization parameters
      DATA STABVEL/0D0/
      DATA STABPOS/0D0/
C
C miscellaneous
      DATA MFRCFLG/0/
      DATA ROUSTATE/0/
      DATA VPKFLG/0/
      DATA INERFLG/0/
      DATA MMFLG/0/
      DATA MMLDUFLG/0/
      DATA WWFLG/0/
      DATA LTAUFLG/0/
      DATA FS0FLG/0/
      DATA II/0/
      DATA MMAP(1)/1/
      DATA MMAP(2)/2/
      DATA MMAP(3)/3/
      DATA MMAP(4)/4/
      DATA MMAP(5)/5/
      DATA MMAP(6)/6/
C
C Which parameters were "?" (1) or "<nominal>?" (3)
      DATA GRAVQ(1)/0/
      DATA GRAVQ(2)/0/
      DATA GRAVQ(3)/0/
      DATA MKQ(1)/0/
      DATA MKQ(2)/0/
      DATA MKQ(3)/0/
      DATA IKQ(1,1,1)/0/
      DATA IKQ(1,1,2)/0/
      DATA IKQ(1,1,3)/0/
      DATA IKQ(1,2,1)/0/
      DATA IKQ(1,2,2)/0/
      DATA IKQ(1,2,3)/0/
      DATA IKQ(1,3,1)/0/
      DATA IKQ(1,3,2)/0/
      DATA IKQ(1,3,3)/0/
      DATA IKQ(2,1,1)/0/
      DATA IKQ(2,1,2)/0/
      DATA IKQ(2,1,3)/0/
      DATA IKQ(2,2,1)/0/
      DATA IKQ(2,2,2)/0/
      DATA IKQ(2,2,3)/0/
      DATA IKQ(2,3,1)/0/
      DATA IKQ(2,3,2)/0/
      DATA IKQ(2,3,3)/0/
      DATA IKQ(3,1,1)/0/
      DATA IKQ(3,1,2)/0/
      DATA IKQ(3,1,3)/0/
      DATA IKQ(3,2,1)/0/
      DATA IKQ(3,2,2)/0/
      DATA IKQ(3,2,3)/0/
      DATA IKQ(3,3,1)/0/
      DATA IKQ(3,3,2)/0/
      DATA IKQ(3,3,3)/0/
      DATA PINQ(1,1)/0/
      DATA PINQ(1,2)/0/
      DATA PINQ(1,3)/0/
      DATA PINQ(2,1)/0/
      DATA PINQ(2,2)/0/
      DATA PINQ(2,3)/0/
      DATA PINQ(3,1)/0/
      DATA PINQ(3,2)/0/
      DATA PINQ(3,3)/0/
      DATA PINQ(4,1)/0/
      DATA PINQ(4,2)/0/
      DATA PINQ(4,3)/0/
      DATA PINQ(5,1)/0/
      DATA PINQ(5,2)/0/
      DATA PINQ(5,3)/0/
      DATA PINQ(6,1)/0/
      DATA PINQ(6,2)/0/
      DATA PINQ(6,3)/0/
      DATA RKQ(1,1)/0/
      DATA RKQ(1,2)/0/
      DATA RKQ(1,3)/0/
      DATA RKQ(2,1)/0/
      DATA RKQ(2,2)/0/
      DATA RKQ(2,3)/0/
      DATA RKQ(3,1)/0/
      DATA RKQ(3,2)/0/
      DATA RKQ(3,3)/0/
      DATA RIQ(1,1)/0/
      DATA RIQ(1,2)/0/
      DATA RIQ(1,3)/0/
      DATA RIQ(2,1)/0/
      DATA RIQ(2,2)/0/
      DATA RIQ(2,3)/0/
      DATA RIQ(3,1)/0/
      DATA RIQ(3,2)/0/
      DATA RIQ(3,3)/0/
      DATA PRESQ(1)/0/
      DATA PRESQ(2)/0/
      DATA PRESQ(3)/3/
      DATA PRESQ(4)/0/
      DATA PRESQ(5)/0/
      DATA PRESQ(6)/0/
      DATA STABVELQ/3/
      DATA STABPOSQ/3/
C
C End of values from input file
C
      END
C
      SUBROUTINE SDINIT
C
C
C Initialization routine
C
C
C  This routine must be called before the first call to sdstate(), after
C  supplying values for any `?' parameters in the input.
C
      INTEGER GROUND,NBOD,NDOF,NCONS,NLOOP,NLDOF,NLOOPC,NBALL,NLBALL,
     & NPRES,NUSER
      INTEGER JTYPE(3),INB(3),OUTB(3),NJNTDOF(3),NJNTC(3),NJNTP(3),
     & FIRSTQ(3),BALLQ(3),FIRSTM(3),FIRSTP(3)
      INTEGER TRANS(6),FIRSTU(2)
      COMMON/SDGTOPO/ GROUND,NBOD,NDOF,NCONS,NLOOP,NLDOF,NLOOPC,NBALL,
     & NLBALL,NPRES,NUSER,JTYPE,INB,OUTB,NJNTDOF,NJNTC,NJNTP,FIRSTQ,
     & BALLQ,FIRSTM,FIRSTP,TRANS,FIRSTU
      DOUBLE PRECISION GRAV(3),MK(3),IK(3,3,3),PIN(6,3)
      DOUBLE PRECISION RK(3,3),RI(3,3),PRES(6),STABVEL,STABPOS
      INTEGER MFRCFLG,ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,
     & LTAUFLG,FS0FLG,II,MMAP(6)
      INTEGER GRAVQ(3),MKQ(3),IKQ(3,3,3),PINQ(6,3),RKQ(3,3),RIQ(3,3),
     & PRESQ(6),STABVELQ,STABPOSQ
      DOUBLE PRECISION MTOT,PSMKG,RHEAD(3,3),RCOM(3,3),MKRCOMT(3,3,3),
     & PSIKG(3,3),PSRCOMG(3),PSRKG(3),PSRIG(3),PSMK(6),PSIK(6,3,3),
     & PSRCOM(6,3),PSRK(6,3),PSRI(6,3)
      COMMON/SDGINPUT/ GRAV,MK,IK,PIN,RK,RI,PRES,STABVEL,STABPOS,RHEAD,
     & RCOM,PSRCOMG,PSRCOM,MKRCOMT,PSMK,PSIK,PSRK,PSRI,PSMKG,PSIKG,PSRKG
     & ,PSRIG,MTOT,MFRCFLG,ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,
     & LTAUFLG,FS0FLG,II,MMAP,GRAVQ,MKQ,IKQ,PINQ,RKQ,RIQ,PRESQ,STABVELQ,
     & STABPOSQ
      DOUBLE PRECISION SUMSQ,NORMINV
      INTEGER I,J,K
      DOUBLE PRECISION CURTIM,Q(7),QN(7),U(6),CNK(6,3,3),CNB(3,3,3)
      DOUBLE PRECISION RNK(6,3),VNK(6,3),WK(6,3),RNB(3,3),VNB(3,3),WB(3,
     & 3),WBRCOM(3,3),COM(3),RNKG(3)
      DOUBLE PRECISION CIK(6,3,3),RIKT(6,3,3),IKO(6,3,3),MKRK(6,3,3),CIB
     & (3,3,3)
      DOUBLE PRECISION WKK(6,3),VKK(6,3),DIK(6,3),RPP(6,3),RPK(6,3),RIK(
     & 6,3),RIK2(6,3)
      DOUBLE PRECISION RPRI(6,3),WIK(6,3),VIK(6,3),WIRK(6,3),RKWKK(6,3),
     & WKRPK(6,3),VIKWKR(6,3)
      DOUBLE PRECISION PERR(3),VERR(3),AERR(3),MULT(3),UFK(3,3),UTK(3,3)
     & ,MFK(3,3),MTK(3,3)
      DOUBLE PRECISION UTAU(6),MTAU(6),UACC(6),UVEL(6),UPOS(7)
      DOUBLE PRECISION S1,C1,S2,C2
      COMMON/SDGSTATE/ CURTIM,Q,QN,U,CNK,CNB,RNKG,RNK,RNB,VNK,VNB,WK,WB,
     & COM,CIK,CIB,RIKT,IKO,MKRK,WKK,VKK,DIK,RPP,RPK,RIK,RIK2,RPRI,WIK,
     & VIK,WIRK,RKWKK,WKRPK,VIKWKR,WBRCOM,PERR,VERR,AERR,MULT,UFK,UTK,
     & UTAU,MFK,MTK,MTAU,UACC,UVEL,UPOS,S1,C1,S2,C2
      DOUBLE PRECISION FS0(6),QDOT(7),OTK(6,3),ATK(6,3),AIOIWI(6,3),
     & FSTAR(6,3)
      DOUBLE PRECISION TSTAR(6,3),FSTARK(6,3),TSTARK(6,3),IKWK(6,3),
     & WKIKWK(6,3),GK(6,3),IKBWK(3,3),WKIKBWK(3,3)
      DOUBLE PRECISION W0W0(3),W1W1(3),W2W2(3),W0W1(3),W0W2(3),W1W2(3)
      DOUBLE PRECISION W00W11(3),W00W22(3),W11W22(3),WW(3,3),QRAUX(3)
      DOUBLE PRECISION MM(6,6),MLO(6,6),MDI(6),IKWPK(6,6,3),WORKS(6),
     & WORKSS(6,6)
      DOUBLE PRECISION WPK(6,6,3),VPK(6,6,3),VWRI(6,6,3)
      INTEGER WMAP(3),MULTMAP(3),JPVT(3),WSIZ,WRANK
      COMMON/SDGLHS/ QDOT,OTK,ATK,AIOIWI,FSTAR,TSTAR,FS0,FSTARK,TSTARK,
     & IKWK,IKBWK,WKIKWK,WKIKBWK,GK,W0W0,W1W1,W2W2,W0W1,W0W2,W1W2,W00W11
     & ,W00W22,W11W22,WW,QRAUX,MM,MLO,MDI,IKWPK,WORKS,WORKSS,WPK,VPK,
     & VWRI,WMAP,MULTMAP,JPVT,WSIZ,WRANK
      DOUBLE PRECISION FS(6),UDOT(6),TAUC(6),DYAD(3,3,3),FC(6,3),TC(6,3)
      DOUBLE PRECISION ANK(6,3),ONK(6,3),ONKB(6,3),AONKRI(6,3),ANKB(6,3)
     & ,ANKATK(6,3),ANB(3,3),ONB(3,3),DYRCOM(3,3)
      DOUBLE PRECISION FFK(6,3),TTK(6,3),FCCIKT(6,3),FFKB(3,3),TTKB(3,3)
      COMMON/SDGRHS/ FS,UDOT,ANK,ANB,ONK,ONB,ONKB,AONKRI,ANKB,ANKATK,
     & DYRCOM,FFK,TTK,FCCIKT,FFKB,TTKB,DYAD,FC,TC,TAUC
      DOUBLE PRECISION TEMP(3000),TMAT1(3,3),TMAT2(3,3),TVEC1(3),TVEC2(3
     & ),TVEC3(3),TVEC4(3),TVEC5(3)
      DOUBLE PRECISION TSC1,TSC2,TSC3
      COMMON/SDGTEMP/ TEMP,TMAT1,TMAT2,TVEC1,TVEC2,TVEC3,TVEC4,TVEC5,
     & TSC1,TSC2,TSC3
      EXTERNAL SDBLKDATA
C
C
C Check that all `?' parameters have been assigned values
C
      DO 100 K=1,3
        IF (GRAVQ(K) .EQ. 1) THEN
          CALL SDSETERR(7,25)
        ENDIF
100   CONTINUE
      DO 140 K=1,3
        IF (MKQ(K) .EQ. 1) THEN
          CALL SDSETERR(7,26)
        ENDIF
        DO 130 I=1,3
          IF (RKQ(K,I) .EQ. 1) THEN
            CALL SDSETERR(7,29)
          ENDIF
          IF (RIQ(K,I) .EQ. 1) THEN
            CALL SDSETERR(7,30)
          ENDIF
          DO 120 J=1,3
            IF (IKQ(K,I,J) .EQ. 1) THEN
              CALL SDSETERR(7,27)
            ENDIF
120       CONTINUE
130     CONTINUE
140   CONTINUE
      DO 160 K=1,6
        DO 150 I=1,3
          IF (PINQ(K,I) .EQ. 1) THEN
            CALL SDSETERR(7,28)
          ENDIF
150     CONTINUE
160   CONTINUE
C
C Normalize pin vectors if necessary
C
C
C Zero out Vpk and Wpk
C
      DO 520 I=1,6
        DO 510 J=I,6
          DO 500 K=1,3
            VPK(I,J,K)= 0D0
            WPK(I,J,K)= 0D0
500       CONTINUE
510     CONTINUE
520   CONTINUE
C
C Compute pseudobody-related constants
C
      RCOM(1,1)= 0D0
      RCOM(1,2)= 0D0
      RCOM(1,3)= 0D0
      RCOM(2,1)= 0D0
      RCOM(2,2)= 0D0
      RCOM(2,3)= 0D0
      RCOM(3,1)= 0D0
      RCOM(3,2)= 0D0
      RCOM(3,3)= 0D0
C
C Compute mass properties-related constants
C
      MTOT= 1D0
      CALL SDSERIALNO(I)
      IF (I .NE. 10001) THEN
        CALL SDSETERR(7,41)
      ENDIF
      ROUSTATE= 1
C
      RETURN
      END
C
C Convert state to form using 1-2-3 Euler angles for ball joints.
C
      SUBROUTINE SDST2ANG(ST,STANG)
      DOUBLE PRECISION ST(7),STANG(6)
C
      INTEGER I
      DOUBLE PRECISION DC(3,3)
C
      DO 100 I=1,6
        STANG(I)= ST(I)
100   CONTINUE
      CALL SDQUAT2DC(ST(4),ST(5),ST(6),ST(7),DC)
      CALL SDDC2ANG(DC,STANG(4),STANG(5),STANG(6))
C
      RETURN
      END
C
C Convert 1-2-3 form of state back to Euler parameters for ball joints.
C
      SUBROUTINE SDANG2ST(STANG,ST)
      DOUBLE PRECISION STANG(6),ST(7)
C
      INTEGER I
      DOUBLE PRECISION DC(3,3)
C
      DO 100 I=1,6
        ST(I)= STANG(I)
100   CONTINUE
      CALL SDANG2DC(STANG(4),STANG(5),STANG(6),DC)
      CALL SDDC2QUAT(DC,ST(4),ST(5),ST(6),ST(7))
C
      RETURN
      END
C
C Normalize Euler parameters in state.
C
      SUBROUTINE SDNRMSTERR(ST,NORMST,ROUTINE)
      DOUBLE PRECISION ST(7),NORMST(7)
      INTEGER ROUTINE
C
      DOUBLE PRECISION GRAV(3),MK(3),IK(3,3,3),PIN(6,3)
      DOUBLE PRECISION RK(3,3),RI(3,3),PRES(6),STABVEL,STABPOS
      INTEGER MFRCFLG,ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,
     & LTAUFLG,FS0FLG,II,MMAP(6)
      INTEGER GRAVQ(3),MKQ(3),IKQ(3,3,3),PINQ(6,3),RKQ(3,3),RIQ(3,3),
     & PRESQ(6),STABVELQ,STABPOSQ
      DOUBLE PRECISION MTOT,PSMKG,RHEAD(3,3),RCOM(3,3),MKRCOMT(3,3,3),
     & PSIKG(3,3),PSRCOMG(3),PSRKG(3),PSRIG(3),PSMK(6),PSIK(6,3,3),
     & PSRCOM(6,3),PSRK(6,3),PSRI(6,3)
      COMMON/SDGINPUT/ GRAV,MK,IK,PIN,RK,RI,PRES,STABVEL,STABPOS,RHEAD,
     & RCOM,PSRCOMG,PSRCOM,MKRCOMT,PSMK,PSIK,PSRK,PSRI,PSMKG,PSIKG,PSRKG
     & ,PSRIG,MTOT,MFRCFLG,ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,
     & LTAUFLG,FS0FLG,II,MMAP,GRAVQ,MKQ,IKQ,PINQ,RKQ,RIQ,PRESQ,STABVELQ,
     & STABPOSQ
      INTEGER I
      DOUBLE PRECISION NORM
C
      DO 100 I=1,7
        NORMST(I)= ST(I)
100   CONTINUE
      NORM= DSQRT(ST(4)*ST(4)+ST(5)*ST(5)+ST(6)*ST(6)+ST(7)*ST(7))
      IF (ROUTINE .NE. 0) THEN
        IF ((NORM .LT. .9D0) .OR. (NORM .GT. 1.1D0)) THEN
          CALL SDSETERR(ROUTINE,14)
        ENDIF
      ENDIF
      IF (NORM .EQ. 0D0) THEN
        NORMST(7)= 1D0
        NORM= 1D0
      ENDIF
      NORM= 1D0/NORM
      NORMST(4)= NORMST(4)*NORM
      NORMST(5)= NORMST(5)*NORM
      NORMST(6)= NORMST(6)*NORM
      NORMST(7)= NORMST(7)*NORM
C
      RETURN
      END
C
      SUBROUTINE SDNORMST(ST,NORMST)
      DOUBLE PRECISION ST(7),NORMST(7)
C
C
      CALL SDNRMSTERR(ST,NORMST,0)
C
      RETURN
      END
C
      SUBROUTINE SDSTATE(TIMEIN,QIN,UIN)
      DOUBLE PRECISION TIMEIN,QIN(7),UIN(6)
C
C
C Compute kinematic information and store it in sdgstate.
C
C Generated TIMESTAMP by SD/FAST, Kane's formulation
C (sdfast 2.0 #10001)
C
      DOUBLE PRECISION GRAV(3),MK(3),IK(3,3,3),PIN(6,3)
      DOUBLE PRECISION RK(3,3),RI(3,3),PRES(6),STABVEL,STABPOS
      INTEGER MFRCFLG,ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,
     & LTAUFLG,FS0FLG,II,MMAP(6)
      INTEGER GRAVQ(3),MKQ(3),IKQ(3,3,3),PINQ(6,3),RKQ(3,3),RIQ(3,3),
     & PRESQ(6),STABVELQ,STABPOSQ
      DOUBLE PRECISION MTOT,PSMKG,RHEAD(3,3),RCOM(3,3),MKRCOMT(3,3,3),
     & PSIKG(3,3),PSRCOMG(3),PSRKG(3),PSRIG(3),PSMK(6),PSIK(6,3,3),
     & PSRCOM(6,3),PSRK(6,3),PSRI(6,3)
      COMMON/SDGINPUT/ GRAV,MK,IK,PIN,RK,RI,PRES,STABVEL,STABPOS,RHEAD,
     & RCOM,PSRCOMG,PSRCOM,MKRCOMT,PSMK,PSIK,PSRK,PSRI,PSMKG,PSIKG,PSRKG
     & ,PSRIG,MTOT,MFRCFLG,ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,
     & LTAUFLG,FS0FLG,II,MMAP,GRAVQ,MKQ,IKQ,PINQ,RKQ,RIQ,PRESQ,STABVELQ,
     & STABPOSQ
      DOUBLE PRECISION CURTIM,Q(7),QN(7),U(6),CNK(6,3,3),CNB(3,3,3)
      DOUBLE PRECISION RNK(6,3),VNK(6,3),WK(6,3),RNB(3,3),VNB(3,3),WB(3,
     & 3),WBRCOM(3,3),COM(3),RNKG(3)
      DOUBLE PRECISION CIK(6,3,3),RIKT(6,3,3),IKO(6,3,3),MKRK(6,3,3),CIB
     & (3,3,3)
      DOUBLE PRECISION WKK(6,3),VKK(6,3),DIK(6,3),RPP(6,3),RPK(6,3),RIK(
     & 6,3),RIK2(6,3)
      DOUBLE PRECISION RPRI(6,3),WIK(6,3),VIK(6,3),WIRK(6,3),RKWKK(6,3),
     & WKRPK(6,3),VIKWKR(6,3)
      DOUBLE PRECISION PERR(3),VERR(3),AERR(3),MULT(3),UFK(3,3),UTK(3,3)
     & ,MFK(3,3),MTK(3,3)
      DOUBLE PRECISION UTAU(6),MTAU(6),UACC(6),UVEL(6),UPOS(7)
      DOUBLE PRECISION S1,C1,S2,C2
      COMMON/SDGSTATE/ CURTIM,Q,QN,U,CNK,CNB,RNKG,RNK,RNB,VNK,VNB,WK,WB,
     & COM,CIK,CIB,RIKT,IKO,MKRK,WKK,VKK,DIK,RPP,RPK,RIK,RIK2,RPRI,WIK,
     & VIK,WIRK,RKWKK,WKRPK,VIKWKR,WBRCOM,PERR,VERR,AERR,MULT,UFK,UTK,
     & UTAU,MFK,MTK,MTAU,UACC,UVEL,UPOS,S1,C1,S2,C2
      DOUBLE PRECISION FS0(6),QDOT(7),OTK(6,3),ATK(6,3),AIOIWI(6,3),
     & FSTAR(6,3)
      DOUBLE PRECISION TSTAR(6,3),FSTARK(6,3),TSTARK(6,3),IKWK(6,3),
     & WKIKWK(6,3),GK(6,3),IKBWK(3,3),WKIKBWK(3,3)
      DOUBLE PRECISION W0W0(3),W1W1(3),W2W2(3),W0W1(3),W0W2(3),W1W2(3)
      DOUBLE PRECISION W00W11(3),W00W22(3),W11W22(3),WW(3,3),QRAUX(3)
      DOUBLE PRECISION MM(6,6),MLO(6,6),MDI(6),IKWPK(6,6,3),WORKS(6),
     & WORKSS(6,6)
      DOUBLE PRECISION WPK(6,6,3),VPK(6,6,3),VWRI(6,6,3)
      INTEGER WMAP(3),MULTMAP(3),JPVT(3),WSIZ,WRANK
      COMMON/SDGLHS/ QDOT,OTK,ATK,AIOIWI,FSTAR,TSTAR,FS0,FSTARK,TSTARK,
     & IKWK,IKBWK,WKIKWK,WKIKBWK,GK,W0W0,W1W1,W2W2,W0W1,W0W2,W1W2,W00W11
     & ,W00W22,W11W22,WW,QRAUX,MM,MLO,MDI,IKWPK,WORKS,WORKSS,WPK,VPK,
     & VWRI,WMAP,MULTMAP,JPVT,WSIZ,WRANK
      DOUBLE PRECISION TEMP(3000),TMAT1(3,3),TMAT2(3,3),TVEC1(3),TVEC2(3
     & ),TVEC3(3),TVEC4(3),TVEC5(3)
      DOUBLE PRECISION TSC1,TSC2,TSC3
      COMMON/SDGTEMP/ TEMP,TMAT1,TMAT2,TVEC1,TVEC2,TVEC3,TVEC4,TVEC5,
     & TSC1,TSC2,TSC3
      INTEGER I,J,QCHG,UCHG
      DOUBLE PRECISION EE,STAB
C
      IF ((ROUSTATE .NE. 1) .AND. (ROUSTATE .NE. 2) .AND. (ROUSTATE
     &  .NE. 3)) THEN
        CALL SDSETERR(8,22)
        RETURN
      ENDIF
      IF (ROUSTATE .EQ. 1) THEN
        DO 50 I=1,6
          IF (PRESQ(I) .EQ. 1) THEN
            CALL SDSETERR(8,31)
          ENDIF
50      CONTINUE
      ENDIF
C
C See if time or any qs have changed since last call
C
      IF ((ROUSTATE .NE. 1) .AND. (TIMEIN .EQ. CURTIM)) THEN
        QCHG= 0
        DO 65 I=1,7
          IF (QIN(I) .NE. Q(I)) THEN
            QCHG= 1
            GOTO 70
          ENDIF
65      CONTINUE
70      CONTINUE
      ELSE
        QCHG= 1
      ENDIF
C
C If time and qs are unchanged, check us
C
      IF (QCHG .EQ. 0) THEN
        UCHG= 0
        DO 75 I=1,6
          IF (UIN(I) .NE. U(I)) THEN
            UCHG= 1
            GOTO 80
          ENDIF
75      CONTINUE
80      CONTINUE
      ELSE
        UCHG= 1
      ENDIF
      CURTIM= TIMEIN
      ROUSTATE= 2
      IF (QCHG .EQ. 0) THEN
C goto skipqs
        GOTO 190
      ENDIF
C
C Position-related variables need to be computed
C
      VPKFLG= 0
      MMFLG= 0
      MMLDUFLG= 0
      WWFLG= 0
      DO 100 I=1,7
        Q(I)= QIN(I)
100   CONTINUE
C
C Normalize Euler parameters in state
C
      CALL SDNRMSTERR(Q,QN,8)
C
C Compute sines and cosines of q
C
      S1= DSIN(Q(1))
      C1= DCOS(Q(1))
      S2= DSIN(Q(2))
      C2= DCOS(Q(2))
C
C Compute across-axis direction cosines Cik
C
      CIK(4,1,1)= (1D0-(2D0*((QN(5)*QN(5))+(QN(6)*QN(6)))))
      CIK(4,1,2)= (2D0*((QN(4)*QN(5))-(QN(6)*QN(7))))
      CIK(4,1,3)= (2D0*((QN(4)*QN(6))+(QN(5)*QN(7))))
      CIK(4,2,1)= (2D0*((QN(4)*QN(5))+(QN(6)*QN(7))))
      CIK(4,2,2)= (1D0-(2D0*((QN(4)*QN(4))+(QN(6)*QN(6)))))
      CIK(4,2,3)= (2D0*((QN(5)*QN(6))-(QN(4)*QN(7))))
      CIK(4,3,1)= (2D0*((QN(4)*QN(6))-(QN(5)*QN(7))))
      CIK(4,3,2)= (2D0*((QN(4)*QN(7))+(QN(5)*QN(6))))
      CIK(4,3,3)= (1D0-(2D0*((QN(4)*QN(4))+(QN(5)*QN(5)))))
C
C Compute across-joint direction cosines Cib
C
      CIB(1,1,2)= (S1*S2)
      CIB(1,1,3)= (S1*C2)
      CIB(1,3,2)= (S2*C1)
      CIB(1,3,3)= (C1*C2)
C
C Compute gravity
C
      GK(4,1)= (9.8D0*((CIK(4,3,1)*S2)-(CIK(4,2,1)*C2)))
      GK(4,2)= (9.8D0*((CIK(4,3,2)*S2)-(CIK(4,2,2)*C2)))
      GK(4,3)= (9.8D0*((CIK(4,3,3)*S2)-(CIK(4,2,3)*C2)))
C
C Compute cnk & cnb (direction cosines in N)
C
      CNK(2,1,2)= (S1*S2)
      CNK(2,1,3)= (S1*C2)
      CNK(2,3,2)= (S2*C1)
      CNK(2,3,3)= (C1*C2)
      CNK(4,1,1)= ((CIK(4,3,1)*CNK(2,1,3))+((CIK(4,1,1)*C1)+(CIK(4,2,1)*
     & CNK(2,1,2))))
      CNK(4,1,2)= ((CIK(4,3,2)*CNK(2,1,3))+((CIK(4,1,2)*C1)+(CIK(4,2,2)*
     & CNK(2,1,2))))
      CNK(4,1,3)= ((CIK(4,3,3)*CNK(2,1,3))+((CIK(4,1,3)*C1)+(CIK(4,2,3)*
     & CNK(2,1,2))))
      CNK(4,2,1)= ((CIK(4,2,1)*C2)-(CIK(4,3,1)*S2))
      CNK(4,2,2)= ((CIK(4,2,2)*C2)-(CIK(4,3,2)*S2))
      CNK(4,2,3)= ((CIK(4,2,3)*C2)-(CIK(4,3,3)*S2))
      CNK(4,3,1)= ((CIK(4,3,1)*CNK(2,3,3))+((CIK(4,2,1)*CNK(2,3,2))-(
     & CIK(4,1,1)*S1)))
      CNK(4,3,2)= ((CIK(4,3,2)*CNK(2,3,3))+((CIK(4,2,2)*CNK(2,3,2))-(
     & CIK(4,1,2)*S1)))
      CNK(4,3,3)= ((CIK(4,3,3)*CNK(2,3,3))+((CIK(4,2,3)*CNK(2,3,2))-(
     & CIK(4,1,3)*S1)))
      CNB(1,1,1)= C1
      CNB(1,1,2)= CNK(2,1,2)
      CNB(1,1,3)= CNK(2,1,3)
      CNB(1,2,1)= 0D0
      CNB(1,2,2)= C2
      CNB(1,2,3)= -S2
      CNB(1,3,1)= -S1
      CNB(1,3,2)= CNK(2,3,2)
      CNB(1,3,3)= CNK(2,3,3)
      CNB(2,1,1)= C1
      CNB(2,1,2)= CNK(2,1,2)
      CNB(2,1,3)= CNK(2,1,3)
      CNB(2,2,1)= 0D0
      CNB(2,2,2)= C2
      CNB(2,2,3)= -S2
      CNB(2,3,1)= -S1
      CNB(2,3,2)= CNK(2,3,2)
      CNB(2,3,3)= CNK(2,3,3)
      CNB(3,1,1)= CNK(4,1,1)
      CNB(3,1,2)= CNK(4,1,2)
      CNB(3,1,3)= CNK(4,1,3)
      CNB(3,2,1)= CNK(4,2,1)
      CNB(3,2,2)= CNK(4,2,2)
      CNB(3,2,3)= CNK(4,2,3)
      CNB(3,3,1)= CNK(4,3,1)
      CNB(3,3,2)= CNK(4,3,2)
      CNB(3,3,3)= CNK(4,3,3)
C
C Compute q-related auxiliary variables
C
C
C Compute rnk & rnb (mass center locations in N)
C
      RNK(3,1)= (CNK(2,1,2)*Q(3))
      RNK(3,2)= (Q(3)*C2)
      RNK(3,3)= (CNK(2,3,2)*Q(3))
      RNB(1,1)= 0D0
      RNB(1,2)= 0D0
      RNB(1,3)= 0D0
      RNB(2,1)= RNK(3,1)
      RNB(2,2)= RNK(3,2)
      RNB(2,3)= RNK(3,3)
      RNB(3,1)= RNK(3,1)
      RNB(3,2)= RNK(3,2)
      RNB(3,3)= RNK(3,3)
C
C Compute com (system mass center location in N)
C
      COM(1)= RNK(3,1)
      COM(2)= RNK(3,2)
      COM(3)= RNK(3,3)
C
C Compute constraint position errors
C
C skipqs
190   CONTINUE
      CALL SDUPERR(CURTIM,Q,PERR(2))
      IF (UCHG .EQ. 0) THEN
C goto skipus
        GOTO 290
      ENDIF
C
C Velocity-related variables need to be computed
C
      INERFLG= 0
      DO 200 I=1,6
        U(I)= UIN(I)
200   CONTINUE
C
C Compute u-related auxiliary variables
C
C
C Compute wk & wb (angular velocities)
C
      WK(2,2)= (U(1)*C2)
      WK(2,3)= -(U(1)*S2)
      WK(4,1)= (U(4)+((CIK(4,3,1)*WK(2,3))+((CIK(4,1,1)*U(2))+(
     & CIK(4,2,1)*WK(2,2)))))
      WK(4,2)= ((CIK(4,3,2)*WK(2,3))+((CIK(4,1,2)*U(2))+(CIK(4,2,2)*
     & WK(2,2))))
      WK(4,3)= ((CIK(4,3,3)*WK(2,3))+((CIK(4,1,3)*U(2))+(CIK(4,2,3)*
     & WK(2,2))))
      WK(5,2)= (U(5)+WK(4,2))
      WK(6,3)= (U(6)+WK(4,3))
      WB(1,1)= U(2)
      WB(1,2)= WK(2,2)
      WB(1,3)= WK(2,3)
      WB(2,1)= U(2)
      WB(2,2)= WK(2,2)
      WB(2,3)= WK(2,3)
      WB(3,1)= WK(4,1)
      WB(3,2)= WK(5,2)
      WB(3,3)= WK(6,3)
C
C Compute auxiliary variables involving wk
C
      WKRPK(3,1)= -(Q(3)*WK(2,3))
      WKRPK(3,3)= (Q(3)*U(2))
C
C Compute temporaries for use in SDRHS
C
      W0W0(1)= (U(2)*U(2))
      W0W0(2)= (U(2)*U(2))
      W0W0(3)= (WK(4,1)*WK(4,1))
      W1W1(1)= (WK(2,2)*WK(2,2))
      W1W1(2)= (WK(2,2)*WK(2,2))
      W1W1(3)= (WK(5,2)*WK(5,2))
      W2W2(1)= (WK(2,3)*WK(2,3))
      W2W2(2)= (WK(2,3)*WK(2,3))
      W2W2(3)= (WK(6,3)*WK(6,3))
      W0W1(1)= (U(2)*WK(2,2))
      W0W1(2)= (U(2)*WK(2,2))
      W0W1(3)= (WK(4,1)*WK(5,2))
      W0W2(1)= (U(2)*WK(2,3))
      W0W2(2)= (U(2)*WK(2,3))
      W0W2(3)= (WK(4,1)*WK(6,3))
      W1W2(1)= (WK(2,2)*WK(2,3))
      W1W2(2)= (WK(2,2)*WK(2,3))
      W1W2(3)= (WK(5,2)*WK(6,3))
      W00W11(1)= -(W0W0(1)+W1W1(1))
      W00W11(2)= -(W0W0(2)+W1W1(2))
      W00W11(3)= -(W0W0(3)+W1W1(3))
      W00W22(1)= -(W0W0(1)+W2W2(1))
      W00W22(2)= -(W0W0(2)+W2W2(2))
      W00W22(3)= -(W0W0(3)+W2W2(3))
      W11W22(1)= -(W1W1(1)+W2W2(1))
      W11W22(2)= -(W1W1(2)+W2W2(2))
      W11W22(3)= -(W1W1(3)+W2W2(3))
C
C Compute vnk & vnb (mass center linear velocities in N)
C
      VNK(3,1)= ((CNK(2,1,3)*WKRPK(3,3))+((CNK(2,1,2)*U(3))+(WKRPK(3,1)*
     & C1)))
      VNK(3,2)= ((U(3)*C2)-(WKRPK(3,3)*S2))
      VNK(3,3)= ((CNK(2,3,3)*WKRPK(3,3))+((CNK(2,3,2)*U(3))-(WKRPK(3,1)*
     & S1)))
      VNB(1,1)= 0D0
      VNB(1,2)= 0D0
      VNB(1,3)= 0D0
      VNB(2,1)= VNK(3,1)
      VNB(2,2)= VNK(3,2)
      VNB(2,3)= VNK(3,3)
      VNB(3,1)= VNK(3,1)
      VNB(3,2)= VNK(3,2)
      VNB(3,3)= VNK(3,3)
C
C Compute qdot (kinematical equations)
C
      QDOT(1)= U(1)
      QDOT(2)= U(2)
      QDOT(3)= U(3)
      QDOT(4)= (.5D0*((Q(7)*U(4))+((Q(5)*U(6))-(Q(6)*U(5)))))
      QDOT(5)= (.5D0*((Q(6)*U(4))+((Q(7)*U(5))-(Q(4)*U(6)))))
      QDOT(6)= (.5D0*(((Q(4)*U(5))+(Q(7)*U(6)))-(Q(5)*U(4))))
      QDOT(7)= -(.5D0*((Q(4)*U(4))+((Q(5)*U(5))+(Q(6)*U(6)))))
      IF (STABVEL  .NE.  0D0) THEN
        EE= ((Q(7)*Q(7))+((Q(6)*Q(6))+((Q(4)*Q(4))+(Q(5)*Q(5)))))
        STAB= ((STABVEL*(1D0-EE))/EE)
        QDOT(4)= (QDOT(4)+(Q(4)*STAB))
        QDOT(5)= (QDOT(5)+(Q(5)*STAB))
        QDOT(6)= (QDOT(6)+(Q(6)*STAB))
        QDOT(7)= (QDOT(7)+(Q(7)*STAB))
      ENDIF
C
C Compute constraint velocity errors
C
C skipus
290   CONTINUE
      CALL SDUVERR(CURTIM,Q,U,VERR(2))
C
C Initialize applied forces and torques to zero
C
      DO 310 I=1,3
        DO 300 J=1,3
          UFK(I,J)= 0D0
          UTK(I,J)= 0D0
300     CONTINUE
310   CONTINUE
      DO 320 I=1,6
        UTAU(I)= 0D0
320   CONTINUE
      LTAUFLG= 0
      FS0FLG= 0
C
C Initialize prescribed motions
C
      UACC(3)= 0D0
      UVEL(3)= U(3)
      UPOS(3)= Q(3)
C
C  Used 0.00 seconds CPU time,
C  0 additional bytes of memory.
C  Equations contain   85 adds/subtracts/negates
C                     135 multiplies
C                       1 divides
C                     181 assignments
C
C
      RETURN
      END
C
      SUBROUTINE SDQDOT(OQDOT)
      DOUBLE PRECISION OQDOT(7)
C
C
C Return position coordinate derivatives for tree joints.
C
      DOUBLE PRECISION GRAV(3),MK(3),IK(3,3,3),PIN(6,3)
      DOUBLE PRECISION RK(3,3),RI(3,3),PRES(6),STABVEL,STABPOS
      INTEGER MFRCFLG,ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,
     & LTAUFLG,FS0FLG,II,MMAP(6)
      INTEGER GRAVQ(3),MKQ(3),IKQ(3,3,3),PINQ(6,3),RKQ(3,3),RIQ(3,3),
     & PRESQ(6),STABVELQ,STABPOSQ
      DOUBLE PRECISION MTOT,PSMKG,RHEAD(3,3),RCOM(3,3),MKRCOMT(3,3,3),
     & PSIKG(3,3),PSRCOMG(3),PSRKG(3),PSRIG(3),PSMK(6),PSIK(6,3,3),
     & PSRCOM(6,3),PSRK(6,3),PSRI(6,3)
      COMMON/SDGINPUT/ GRAV,MK,IK,PIN,RK,RI,PRES,STABVEL,STABPOS,RHEAD,
     & RCOM,PSRCOMG,PSRCOM,MKRCOMT,PSMK,PSIK,PSRK,PSRI,PSMKG,PSIKG,PSRKG
     & ,PSRIG,MTOT,MFRCFLG,ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,
     & LTAUFLG,FS0FLG,II,MMAP,GRAVQ,MKQ,IKQ,PINQ,RKQ,RIQ,PRESQ,STABVELQ,
     & STABPOSQ
      DOUBLE PRECISION FS0(6),QDOT(7),OTK(6,3),ATK(6,3),AIOIWI(6,3),
     & FSTAR(6,3)
      DOUBLE PRECISION TSTAR(6,3),FSTARK(6,3),TSTARK(6,3),IKWK(6,3),
     & WKIKWK(6,3),GK(6,3),IKBWK(3,3),WKIKBWK(3,3)
      DOUBLE PRECISION W0W0(3),W1W1(3),W2W2(3),W0W1(3),W0W2(3),W1W2(3)
      DOUBLE PRECISION W00W11(3),W00W22(3),W11W22(3),WW(3,3),QRAUX(3)
      DOUBLE PRECISION MM(6,6),MLO(6,6),MDI(6),IKWPK(6,6,3),WORKS(6),
     & WORKSS(6,6)
      DOUBLE PRECISION WPK(6,6,3),VPK(6,6,3),VWRI(6,6,3)
      INTEGER WMAP(3),MULTMAP(3),JPVT(3),WSIZ,WRANK
      COMMON/SDGLHS/ QDOT,OTK,ATK,AIOIWI,FSTAR,TSTAR,FS0,FSTARK,TSTARK,
     & IKWK,IKBWK,WKIKWK,WKIKBWK,GK,W0W0,W1W1,W2W2,W0W1,W0W2,W1W2,W00W11
     & ,W00W22,W11W22,WW,QRAUX,MM,MLO,MDI,IKWPK,WORKS,WORKSS,WPK,VPK,
     & VWRI,WMAP,MULTMAP,JPVT,WSIZ,WRANK
      INTEGER I
C
      IF ((ROUSTATE .NE. 2) .AND. (ROUSTATE .NE. 3)) THEN
        CALL SDSETERR(63,23)
        RETURN
      ENDIF
      DO 100 I=1,7
        OQDOT(I)= QDOT(I)
100   CONTINUE
C
      RETURN
      END
C
      SUBROUTINE SDU2QDOT(UIN,OQDOT)
      DOUBLE PRECISION UIN(6),OQDOT(7)
C
C
C Convert velocities to qdots.
C
      DOUBLE PRECISION GRAV(3),MK(3),IK(3,3,3),PIN(6,3)
      DOUBLE PRECISION RK(3,3),RI(3,3),PRES(6),STABVEL,STABPOS
      INTEGER MFRCFLG,ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,
     & LTAUFLG,FS0FLG,II,MMAP(6)
