      COMMON/SDGTEMP/ TEMP,TMAT1,TMAT2,TVEC1,TVEC2,TVEC3,TVEC4,TVEC5,
     & TSC1,TSC2,TSC3
C
C
C Compute Fs (multiplier-generated forces only)
C
      CALL SDDOVPK
      FS(1)= (MTAU(1)-((((MTK(1,3)*S2)-(MTK(1,2)*C2))+(((MTK(2,3)*S2)-(
     & MTK(2,2)*C2))-(MFK(2,1)*VPK(1,3,1))))-(((MFK(3,3)*VPK(1,4,3))+((
     & MFK(3,1)*VPK(1,4,1))+(MFK(3,2)*VPK(1,4,2))))+((MTK(3,3)*
     & WPK(1,4,3))+((MTK(3,1)*WPK(1,4,1))+(MTK(3,2)*WPK(1,4,2)))))))
      FS(2)= (MTAU(2)+((MTK(1,1)+(MTK(2,1)+(MFK(2,3)*Q(3))))+(((
     & CIK(4,1,3)*MTK(3,3))+((CIK(4,1,1)*MTK(3,1))+(CIK(4,1,2)*MTK(3,2))
     & ))+((MFK(3,3)*VPK(2,4,3))+((MFK(3,1)*VPK(2,4,1))+(MFK(3,2)*
     & VPK(2,4,2)))))))
      FS(3)= (MTAU(3)+(MFK(2,2)+((CIK(4,2,3)*MFK(3,3))+((CIK(4,2,1)*
     & MFK(3,1))+(CIK(4,2,2)*MFK(3,2))))))
      FS(4)= (MTAU(4)+MTK(3,1))
      FS(5)= (MTAU(5)+MTK(3,2))
      FS(6)= (MTAU(6)+MTK(3,3))
C
C  Used 0.00 seconds CPU time,
C  0 additional bytes of memory.
C  Equations contain   27 adds/subtracts/negates
C                      21 multiplies
C                       0 divides
C                       6 assignments
C
C
      RETURN
      END
