     & PSRCOM(6,3),PSRK(6,3),PSRI(6,3)
      COMMON/SDGINPUT/ GRAV,MK,IK,PIN,RK,RI,PRES,STABVEL,STABPOS,RHEAD,
     & RCOM,PSRCOMG,PSRCOM,MKRCOMT,PSMK,PSIK,PSRK,PSRI,PSMKG,PSIKG,PSRKG
     & ,PSRIG,MTOT,MFRCFLG,ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,
     & LTAUFLG,FS0FLG,II,MMAP,GRAVQ,MKQ,IKQ,PINQ,RKQ,RIQ,PRESQ,STABVELQ,
     & STABPOSQ
      DOUBLE PRECISION CURTIM,Q(7),QN(7),U(6),CNK(6,3,3),CNB(3,3,3)
      DOUBLE PRECISION RNK(6,3),VNK(6,3),WK(6,3),RNB(3,3),VNB(3,3),WB(3,
     & 3),WBRCOM(3,3),COM(3),RNKG(3)
      DOUBLE PRECISION CIK(6,3,3),RIKT(6,3,3),IKO(6,3,3),MKRK(6,3,3),CIB
     & (3,3,3)
      DOUBLE PRECISION WKK(6,3),VKK(6,3),DIK(6,3),RPP(6,3),RPK(6,3),RIK(
     & 6,3),RIK2(6,3)
      DOUBLE PRECISION RPRI(6,3),WIK(6,3),VIK(6,3),WIRK(6,3),RKWKK(6,3),
     & WKRPK(6,3),VIKWKR(6,3)
      DOUBLE PRECISION PERR(3),VERR(3),AERR(3),MULT(3),UFK(3,3),UTK(3,3)
     & ,MFK(3,3),MTK(3,3)
      DOUBLE PRECISION UTAU(6),MTAU(6),UACC(6),UVEL(6),UPOS(7)
      DOUBLE PRECISION S1,C1,S2,C2
      COMMON/SDGSTATE/ CURTIM,Q,QN,U,CNK,CNB,RNKG,RNK,RNB,VNK,VNB,WK,WB,
     & COM,CIK,CIB,RIKT,IKO,MKRK,WKK,VKK,DIK,RPP,RPK,RIK,RIK2,RPRI,WIK,
     & VIK,WIRK,RKWKK,WKRPK,VIKWKR,WBRCOM,PERR,VERR,AERR,MULT,UFK,UTK,
     & UTAU,MFK,MTK,MTAU,UACC,UVEL,UPOS,S1,C1,S2,C2
      DOUBLE PRECISION FS0(6),QDOT(7),OTK(6,3),ATK(6,3),AIOIWI(6,3),
     & FSTAR(6,3)
      DOUBLE PRECISION TSTAR(6,3),FSTARK(6,3),TSTARK(6,3),IKWK(6,3),
     & WKIKWK(6,3),GK(6,3),IKBWK(3,3),WKIKBWK(3,3)
      DOUBLE PRECISION W0W0(3),W1W1(3),W2W2(3),W0W1(3),W0W2(3),W1W2(3)
      DOUBLE PRECISION W00W11(3),W00W22(3),W11W22(3),WW(3,3),QRAUX(3)
      DOUBLE PRECISION MM(6,6),MLO(6,6),MDI(6),IKWPK(6,6,3),WORKS(6),
     & WORKSS(6,6)
      DOUBLE PRECISION WPK(6,6,3),VPK(6,6,3),VWRI(6,6,3)
      INTEGER WMAP(3),MULTMAP(3),JPVT(3),WSIZ,WRANK
      COMMON/SDGLHS/ QDOT,OTK,ATK,AIOIWI,FSTAR,TSTAR,FS0,FSTARK,TSTARK,
     & IKWK,IKBWK,WKIKWK,WKIKBWK,GK,W0W0,W1W1,W2W2,W0W1,W0W2,W1W2,W00W11
     & ,W00W22,W11W22,WW,QRAUX,MM,MLO,MDI,IKWPK,WORKS,WORKSS,WPK,VPK,
     & VWRI,WMAP,MULTMAP,JPVT,WSIZ,WRANK
      DOUBLE PRECISION FS(6),UDOT(6),TAUC(6),DYAD(3,3,3),FC(6,3),TC(6,3)
      DOUBLE PRECISION ANK(6,3),ONK(6,3),ONKB(6,3),AONKRI(6,3),ANKB(6,3)
     & ,ANKATK(6,3),ANB(3,3),ONB(3,3),DYRCOM(3,3)
      DOUBLE PRECISION FFK(6,3),TTK(6,3),FCCIKT(6,3),FFKB(3,3),TTKB(3,3)
      COMMON/SDGRHS/ FS,UDOT,ANK,ANB,ONK,ONB,ONKB,AONKRI,ANKB,ANKATK,
     & DYRCOM,FFK,TTK,FCCIKT,FFKB,TTKB,DYAD,FC,TC,TAUC
      DOUBLE PRECISION TEMP(3000),TMAT1(3,3),TMAT2(3,3),TVEC1(3),TVEC2(3
     & ),TVEC3(3),TVEC4(3),TVEC5(3)
      DOUBLE PRECISION TSC1,TSC2,TSC3
      COMMON/SDGTEMP/ TEMP,TMAT1,TMAT2,TVEC1,TVEC2,TVEC3,TVEC4,TVEC5,
     & TSC1,TSC2,TSC3
C
C
C Compute Fs (incl generic mult & other forces)
C
      CALL SDFSGENMULT
      FS(1)= (FS(1)+FS0(1))
      FS(2)= (FS(2)+FS0(2))
      FS(3)= (FS(3)+FS0(3))
      FS(4)= (FS(4)+FS0(4))
      FS(5)= (FS(5)+FS0(5))
      FS(6)= (FS(6)+FS0(6))
C
C  Used 0.00 seconds CPU time,
C  0 additional bytes of memory.
C  Equations contain    6 adds/subtracts/negates
C                       0 multiplies
C                       0 divides
C                       6 assignments
C
C
      RETURN
      END
C
      SUBROUTINE SDFULLTRQ(UDOTIN,MULTIN,TRQOUT)
      DOUBLE PRECISION UDOTIN(6),MULTIN(3),TRQOUT(6)
C
C Compute hinge torques which would produce indicated udots
C
      DOUBLE PRECISION GRAV(3),MK(3),IK(3,3,3),PIN(6,3)
      DOUBLE PRECISION RK(3,3),RI(3,3),PRES(6),STABVEL,STABPOS
      INTEGER MFRCFLG,ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,
     & LTAUFLG,FS0FLG,II,MMAP(6)
      INTEGER GRAVQ(3),MKQ(3),IKQ(3,3,3),PINQ(6,3),RKQ(3,3),RIQ(3,3),
     & PRESQ(6),STABVELQ,STABPOSQ
      DOUBLE PRECISION MTOT,PSMKG,RHEAD(3,3),RCOM(3,3),MKRCOMT(3,3,3),
     & PSIKG(3,3),PSRCOMG(3),PSRKG(3),PSRIG(3),PSMK(6),PSIK(6,3,3),
     & PSRCOM(6,3),PSRK(6,3),PSRI(6,3)
      COMMON/SDGINPUT/ GRAV,MK,IK,PIN,RK,RI,PRES,STABVEL,STABPOS,RHEAD,
     & RCOM,PSRCOMG,PSRCOM,MKRCOMT,PSMK,PSIK,PSRK,PSRI,PSMKG,PSIKG,PSRKG
     & ,PSRIG,MTOT,MFRCFLG,ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,
     & LTAUFLG,FS0FLG,II,MMAP,GRAVQ,MKQ,IKQ,PINQ,RKQ,RIQ,PRESQ,STABVELQ,
     & STABPOSQ
      DOUBLE PRECISION CURTIM,Q(7),QN(7),U(6),CNK(6,3,3),CNB(3,3,3)
      DOUBLE PRECISION RNK(6,3),VNK(6,3),WK(6,3),RNB(3,3),VNB(3,3),WB(3,
     & 3),WBRCOM(3,3),COM(3),RNKG(3)
      DOUBLE PRECISION CIK(6,3,3),RIKT(6,3,3),IKO(6,3,3),MKRK(6,3,3),CIB
     & (3,3,3)
      DOUBLE PRECISION WKK(6,3),VKK(6,3),DIK(6,3),RPP(6,3),RPK(6,3),RIK(
     & 6,3),RIK2(6,3)
      DOUBLE PRECISION RPRI(6,3),WIK(6,3),VIK(6,3),WIRK(6,3),RKWKK(6,3),
     & WKRPK(6,3),VIKWKR(6,3)
      DOUBLE PRECISION PERR(3),VERR(3),AERR(3),MULT(3),UFK(3,3),UTK(3,3)
     & ,MFK(3,3),MTK(3,3)
      DOUBLE PRECISION UTAU(6),MTAU(6),UACC(6),UVEL(6),UPOS(7)
      DOUBLE PRECISION S1,C1,S2,C2
      COMMON/SDGSTATE/ CURTIM,Q,QN,U,CNK,CNB,RNKG,RNK,RNB,VNK,VNB,WK,WB,
     & COM,CIK,CIB,RIKT,IKO,MKRK,WKK,VKK,DIK,RPP,RPK,RIK,RIK2,RPRI,WIK,
     & VIK,WIRK,RKWKK,WKRPK,VIKWKR,WBRCOM,PERR,VERR,AERR,MULT,UFK,UTK,
     & UTAU,MFK,MTK,MTAU,UACC,UVEL,UPOS,S1,C1,S2,C2
      DOUBLE PRECISION FS0(6),QDOT(7),OTK(6,3),ATK(6,3),AIOIWI(6,3),
     & FSTAR(6,3)
      DOUBLE PRECISION TSTAR(6,3),FSTARK(6,3),TSTARK(6,3),IKWK(6,3),
     & WKIKWK(6,3),GK(6,3),IKBWK(3,3),WKIKBWK(3,3)
      DOUBLE PRECISION W0W0(3),W1W1(3),W2W2(3),W0W1(3),W0W2(3),W1W2(3)
      DOUBLE PRECISION W00W11(3),W00W22(3),W11W22(3),WW(3,3),QRAUX(3)
      DOUBLE PRECISION MM(6,6),MLO(6,6),MDI(6),IKWPK(6,6,3),WORKS(6),
     & WORKSS(6,6)
      DOUBLE PRECISION WPK(6,6,3),VPK(6,6,3),VWRI(6,6,3)
      INTEGER WMAP(3),MULTMAP(3),JPVT(3),WSIZ,WRANK
      COMMON/SDGLHS/ QDOT,OTK,ATK,AIOIWI,FSTAR,TSTAR,FS0,FSTARK,TSTARK,
     & IKWK,IKBWK,WKIKWK,WKIKBWK,GK,W0W0,W1W1,W2W2,W0W1,W0W2,W1W2,W00W11
     & ,W00W22,W11W22,WW,QRAUX,MM,MLO,MDI,IKWPK,WORKS,WORKSS,WPK,VPK,
     & VWRI,WMAP,MULTMAP,JPVT,WSIZ,WRANK
      DOUBLE PRECISION FS(6),UDOT(6),TAUC(6),DYAD(3,3,3),FC(6,3),TC(6,3)
      DOUBLE PRECISION ANK(6,3),ONK(6,3),ONKB(6,3),AONKRI(6,3),ANKB(6,3)
     & ,ANKATK(6,3),ANB(3,3),ONB(3,3),DYRCOM(3,3)
      DOUBLE PRECISION FFK(6,3),TTK(6,3),FCCIKT(6,3),FFKB(3,3),TTKB(3,3)
      COMMON/SDGRHS/ FS,UDOT,ANK,ANB,ONK,ONB,ONKB,AONKRI,ANKB,ANKATK,
     & DYRCOM,FFK,TTK,FCCIKT,FFKB,TTKB,DYAD,FC,TC,TAUC
      DOUBLE PRECISION TEMP(3000),TMAT1(3,3),TMAT2(3,3),TVEC1(3),TVEC2(3
     & ),TVEC3(3),TVEC4(3),TVEC5(3)
      DOUBLE PRECISION TSC1,TSC2,TSC3
      COMMON/SDGTEMP/ TEMP,TMAT1,TMAT2,TVEC1,TVEC2,TVEC3,TVEC4,TVEC5,
     & TSC1,TSC2,TSC3
      DOUBLE PRECISION FSTARR(6,3),TSTARR(6,3),OTKR(6,3),ATIR(6,3),ATKR(
     & 6,3)
C
      IF ((ROUSTATE .NE. 2) .AND. (ROUSTATE .NE. 3)) THEN
        CALL SDSETERR(61,23)
        RETURN
      ENDIF
C
C Compute multiplier-generated forces
C
      CALL SDMFRC(MULTIN)
C
C Account for inertial accelerations and supplied udots
C
      OTKR(2,2)= ((U(2)*WK(2,3))+(UDOTIN(1)*C2))
      OTKR(2,3)= -((U(2)*WK(2,2))+(UDOTIN(1)*S2))
      OTKR(4,1)= (UDOTIN(4)+((CIK(4,3,1)*OTKR(2,3))+((CIK(4,1,1)*
     & UDOTIN(2))+(CIK(4,2,1)*OTKR(2,2)))))
      OTKR(4,2)= ((CIK(4,3,2)*OTKR(2,3))+((CIK(4,1,2)*UDOTIN(2))+(
     & CIK(4,2,2)*OTKR(2,2))))
      OTKR(4,3)= ((CIK(4,3,3)*OTKR(2,3))+((CIK(4,1,3)*UDOTIN(2))+(
     & CIK(4,2,3)*OTKR(2,2))))
      OTKR(5,2)= (OTKR(4,2)+UDOTIN(5))
      OTKR(6,1)= (OTKR(4,1)+((U(6)*WK(5,2))-(U(5)*WK(6,3))))
      OTKR(6,2)= (OTKR(5,2)+((U(4)*WK(6,3))-(U(6)*WK(4,1))))
      OTKR(6,3)= (OTKR(4,3)+(UDOTIN(6)+((U(5)*WK(4,1))-(U(4)*WK(5,2)))))
      ATKR(3,1)= (((WK(2,2)*WKRPK(3,3))-(OTKR(2,3)*Q(3)))-(2D0*(U(3)*
     & WK(2,3))))
      ATKR(3,2)= (UDOTIN(3)+((WK(2,3)*WKRPK(3,1))-(U(2)*WKRPK(3,3))))
      ATKR(3,3)= ((2D0*(U(2)*U(3)))+((Q(3)*UDOTIN(2))-(WK(2,2)*
     & WKRPK(3,1))))
      ATKR(4,1)= ((ATKR(3,3)*CIK(4,3,1))+((ATKR(3,1)*CIK(4,1,1))+(
     & ATKR(3,2)*CIK(4,2,1))))
      ATKR(4,2)= ((ATKR(3,3)*CIK(4,3,2))+((ATKR(3,1)*CIK(4,1,2))+(
     & ATKR(3,2)*CIK(4,2,2))))
      ATKR(4,3)= ((ATKR(3,3)*CIK(4,3,3))+((ATKR(3,1)*CIK(4,1,3))+(
     & ATKR(3,2)*CIK(4,2,3))))
C
C Accumulate all forces and torques
C
      FSTARR(2,1)= (MFK(1,1)+UFK(1,1))
      FSTARR(2,2)= (MFK(1,2)+UFK(1,2))
      FSTARR(2,3)= (MFK(1,3)+UFK(1,3))
      FSTARR(3,1)= (MFK(2,1)+UFK(2,1))
      FSTARR(3,2)= (MFK(2,2)+UFK(2,2))
      FSTARR(3,3)= (MFK(2,3)+UFK(2,3))
      FSTARR(6,1)= ((GK(4,1)-ATKR(4,1))+(MFK(3,1)+UFK(3,1)))
      FSTARR(6,2)= ((GK(4,2)-ATKR(4,2))+(MFK(3,2)+UFK(3,2)))
      FSTARR(6,3)= ((GK(4,3)-ATKR(4,3))+(MFK(3,3)+UFK(3,3)))
      TSTARR(2,1)= (MTK(1,1)+UTK(1,1))
      TSTARR(2,2)= (MTK(1,2)+UTK(1,2))
      TSTARR(2,3)= (MTK(1,3)+UTK(1,3))
      TSTARR(3,1)= (MTK(2,1)+UTK(2,1))
      TSTARR(3,2)= (MTK(2,2)+UTK(2,2))
      TSTARR(3,3)= (MTK(2,3)+UTK(2,3))
      TSTARR(6,1)= ((MTK(3,1)+UTK(3,1))-(.4D0*OTKR(6,1)))
      TSTARR(6,2)= ((MTK(3,2)+UTK(3,2))-(.4D0*OTKR(6,2)))
      TSTARR(6,3)= ((MTK(3,3)+UTK(3,3))-(.4D0*OTKR(6,3)))
C
C Now calculate the torques
C
      CALL SDDOVPK
      TRQOUT(1)= -((MTAU(1)+UTAU(1))+((((FSTARR(3,1)*VPK(1,3,1))+((
     & TSTARR(3,2)*C2)-(TSTARR(3,3)*S2)))+((TSTARR(2,2)*C2)-(TSTARR(2,3)
     & *S2)))+(((FSTARR(6,3)*VPK(1,4,3))+((FSTARR(6,1)*VPK(1,4,1))+(
     & FSTARR(6,2)*VPK(1,4,2))))+((TSTARR(6,3)*WPK(1,4,3))+((TSTARR(6,1)
     & *WPK(1,4,1))+(TSTARR(6,2)*WPK(1,4,2)))))))
      TRQOUT(2)= -((MTAU(2)+UTAU(2))+((TSTARR(2,1)+(TSTARR(3,1)+(
     & FSTARR(3,3)*Q(3))))+(((CIK(4,1,3)*TSTARR(6,3))+((CIK(4,1,1)*
     & TSTARR(6,1))+(CIK(4,1,2)*TSTARR(6,2))))+((FSTARR(6,3)*VPK(2,4,3))
     & +((FSTARR(6,1)*VPK(2,4,1))+(FSTARR(6,2)*VPK(2,4,2)))))))
      TRQOUT(3)= -((FSTARR(3,2)+((CIK(4,2,3)*FSTARR(6,3))+((CIK(4,2,1)*
     & FSTARR(6,1))+(CIK(4,2,2)*FSTARR(6,2)))))+(MTAU(3)+UTAU(3)))
      TRQOUT(4)= -(TSTARR(6,1)+(MTAU(4)+UTAU(4)))
      TRQOUT(5)= -(TSTARR(6,2)+(MTAU(5)+UTAU(5)))
      TRQOUT(6)= -(TSTARR(6,3)+(MTAU(6)+UTAU(6)))
C
C Op counts below do not include called subroutines
C
C
C  Used 0.00 seconds CPU time,
C  0 additional bytes of memory.
C  Equations contain   96 adds/subtracts/negates
C                      62 multiplies
C                       0 divides
C                      39 assignments
C
C
      RETURN
      END
C
      SUBROUTINE SDCOMPTRQ(UDOTIN,TRQOUT)
      DOUBLE PRECISION UDOTIN(6),TRQOUT(6)
C
C Compute hinge torques to produce these udots, ignoring constraints
C
      DOUBLE PRECISION GRAV(3),MK(3),IK(3,3,3),PIN(6,3)
      DOUBLE PRECISION RK(3,3),RI(3,3),PRES(6),STABVEL,STABPOS
      INTEGER MFRCFLG,ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,
     & LTAUFLG,FS0FLG,II,MMAP(6)
      INTEGER GRAVQ(3),MKQ(3),IKQ(3,3,3),PINQ(6,3),RKQ(3,3),RIQ(3,3),
     & PRESQ(6),STABVELQ,STABPOSQ
      DOUBLE PRECISION MTOT,PSMKG,RHEAD(3,3),RCOM(3,3),MKRCOMT(3,3,3),
     & PSIKG(3,3),PSRCOMG(3),PSRKG(3),PSRIG(3),PSMK(6),PSIK(6,3,3),
     & PSRCOM(6,3),PSRK(6,3),PSRI(6,3)
      COMMON/SDGINPUT/ GRAV,MK,IK,PIN,RK,RI,PRES,STABVEL,STABPOS,RHEAD,
     & RCOM,PSRCOMG,PSRCOM,MKRCOMT,PSMK,PSIK,PSRK,PSRI,PSMKG,PSIKG,PSRKG
     & ,PSRIG,MTOT,MFRCFLG,ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,
     & LTAUFLG,FS0FLG,II,MMAP,GRAVQ,MKQ,IKQ,PINQ,RKQ,RIQ,PRESQ,STABVELQ,
     & STABPOSQ
      INTEGER I
      DOUBLE PRECISION MULTIN(3)
C
      IF ((ROUSTATE .NE. 2) .AND. (ROUSTATE .NE. 3)) THEN
        CALL SDSETERR(60,23)
        RETURN
      ENDIF
      DO 100 I=1,3
        MULTIN(I)= 0D0
100   CONTINUE
      CALL SDFULLTRQ(UDOTIN,MULTIN,TRQOUT)
C
      RETURN
      END
C
      SUBROUTINE SDMULTTRQ(MULTIN,TRQOUT)
      DOUBLE PRECISION MULTIN(3),TRQOUT(6)
C
C Compute hinge trqs which would be produced by these mults.
C
      DOUBLE PRECISION GRAV(3),MK(3),IK(3,3,3),PIN(6,3)
      DOUBLE PRECISION RK(3,3),RI(3,3),PRES(6),STABVEL,STABPOS
      INTEGER MFRCFLG,ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,
     & LTAUFLG,FS0FLG,II,MMAP(6)
      INTEGER GRAVQ(3),MKQ(3),IKQ(3,3,3),PINQ(6,3),RKQ(3,3),RIQ(3,3),
     & PRESQ(6),STABVELQ,STABPOSQ
      DOUBLE PRECISION MTOT,PSMKG,RHEAD(3,3),RCOM(3,3),MKRCOMT(3,3,3),
     & PSIKG(3,3),PSRCOMG(3),PSRKG(3),PSRIG(3),PSMK(6),PSIK(6,3,3),
     & PSRCOM(6,3),PSRK(6,3),PSRI(6,3)
      COMMON/SDGINPUT/ GRAV,MK,IK,PIN,RK,RI,PRES,STABVEL,STABPOS,RHEAD,
     & RCOM,PSRCOMG,PSRCOM,MKRCOMT,PSMK,PSIK,PSRK,PSRI,PSMKG,PSIKG,PSRKG
     & ,PSRIG,MTOT,MFRCFLG,ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,
     & LTAUFLG,FS0FLG,II,MMAP,GRAVQ,MKQ,IKQ,PINQ,RKQ,RIQ,PRESQ,STABVELQ,
     & STABPOSQ
      DOUBLE PRECISION FS(6),UDOT(6),TAUC(6),DYAD(3,3,3),FC(6,3),TC(6,3)
      DOUBLE PRECISION ANK(6,3),ONK(6,3),ONKB(6,3),AONKRI(6,3),ANKB(6,3)
     & ,ANKATK(6,3),ANB(3,3),ONB(3,3),DYRCOM(3,3)
      DOUBLE PRECISION FFK(6,3),TTK(6,3),FCCIKT(6,3),FFKB(3,3),TTKB(3,3)
      COMMON/SDGRHS/ FS,UDOT,ANK,ANB,ONK,ONB,ONKB,AONKRI,ANKB,ANKATK,
     & DYRCOM,FFK,TTK,FCCIKT,FFKB,TTKB,DYAD,FC,TC,TAUC
      INTEGER I
C
      IF ((ROUSTATE .NE. 2) .AND. (ROUSTATE .NE. 3)) THEN
        CALL SDSETERR(65,23)
        RETURN
      ENDIF
      CALL SDMFRC(MULTIN)
      CALL SDFSMULT
      DO 100 I=1,6
        TRQOUT(I)= FS(I)
100   CONTINUE
C
      RETURN
      END
C
      SUBROUTINE SDRHS
C
C
C Generated TIMESTAMP by SD/FAST, Kane's formulation
C (sdfast 2.0 #10001)
C
      DOUBLE PRECISION GRAV(3),MK(3),IK(3,3,3),PIN(6,3)
      DOUBLE PRECISION RK(3,3),RI(3,3),PRES(6),STABVEL,STABPOS
      INTEGER MFRCFLG,ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,
     & LTAUFLG,FS0FLG,II,MMAP(6)
      INTEGER GRAVQ(3),MKQ(3),IKQ(3,3,3),PINQ(6,3),RKQ(3,3),RIQ(3,3),
     & PRESQ(6),STABVELQ,STABPOSQ
      DOUBLE PRECISION MTOT,PSMKG,RHEAD(3,3),RCOM(3,3),MKRCOMT(3,3,3),
     & PSIKG(3,3),PSRCOMG(3),PSRKG(3),PSRIG(3),PSMK(6),PSIK(6,3,3),
     & PSRCOM(6,3),PSRK(6,3),PSRI(6,3)
      COMMON/SDGINPUT/ GRAV,MK,IK,PIN,RK,RI,PRES,STABVEL,STABPOS,RHEAD,
     & RCOM,PSRCOMG,PSRCOM,MKRCOMT,PSMK,PSIK,PSRK,PSRI,PSMKG,PSIKG,PSRKG
     & ,PSRIG,MTOT,MFRCFLG,ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,
     & LTAUFLG,FS0FLG,II,MMAP,GRAVQ,MKQ,IKQ,PINQ,RKQ,RIQ,PRESQ,STABVELQ,
     & STABPOSQ
      DOUBLE PRECISION CURTIM,Q(7),QN(7),U(6),CNK(6,3,3),CNB(3,3,3)
      DOUBLE PRECISION RNK(6,3),VNK(6,3),WK(6,3),RNB(3,3),VNB(3,3),WB(3,
     & 3),WBRCOM(3,3),COM(3),RNKG(3)
      DOUBLE PRECISION CIK(6,3,3),RIKT(6,3,3),IKO(6,3,3),MKRK(6,3,3),CIB
     & (3,3,3)
      DOUBLE PRECISION WKK(6,3),VKK(6,3),DIK(6,3),RPP(6,3),RPK(6,3),RIK(
     & 6,3),RIK2(6,3)
      DOUBLE PRECISION RPRI(6,3),WIK(6,3),VIK(6,3),WIRK(6,3),RKWKK(6,3),
     & WKRPK(6,3),VIKWKR(6,3)
      DOUBLE PRECISION PERR(3),VERR(3),AERR(3),MULT(3),UFK(3,3),UTK(3,3)
     & ,MFK(3,3),MTK(3,3)
      DOUBLE PRECISION UTAU(6),MTAU(6),UACC(6),UVEL(6),UPOS(7)
      DOUBLE PRECISION S1,C1,S2,C2
      COMMON/SDGSTATE/ CURTIM,Q,QN,U,CNK,CNB,RNKG,RNK,RNB,VNK,VNB,WK,WB,
     & COM,CIK,CIB,RIKT,IKO,MKRK,WKK,VKK,DIK,RPP,RPK,RIK,RIK2,RPRI,WIK,
     & VIK,WIRK,RKWKK,WKRPK,VIKWKR,WBRCOM,PERR,VERR,AERR,MULT,UFK,UTK,
     & UTAU,MFK,MTK,MTAU,UACC,UVEL,UPOS,S1,C1,S2,C2
      DOUBLE PRECISION FS0(6),QDOT(7),OTK(6,3),ATK(6,3),AIOIWI(6,3),
     & FSTAR(6,3)
      DOUBLE PRECISION TSTAR(6,3),FSTARK(6,3),TSTARK(6,3),IKWK(6,3),
     & WKIKWK(6,3),GK(6,3),IKBWK(3,3),WKIKBWK(3,3)
      DOUBLE PRECISION W0W0(3),W1W1(3),W2W2(3),W0W1(3),W0W2(3),W1W2(3)
      DOUBLE PRECISION W00W11(3),W00W22(3),W11W22(3),WW(3,3),QRAUX(3)
      DOUBLE PRECISION MM(6,6),MLO(6,6),MDI(6),IKWPK(6,6,3),WORKS(6),
     & WORKSS(6,6)
      DOUBLE PRECISION WPK(6,6,3),VPK(6,6,3),VWRI(6,6,3)
      INTEGER WMAP(3),MULTMAP(3),JPVT(3),WSIZ,WRANK
      COMMON/SDGLHS/ QDOT,OTK,ATK,AIOIWI,FSTAR,TSTAR,FS0,FSTARK,TSTARK,
     & IKWK,IKBWK,WKIKWK,WKIKBWK,GK,W0W0,W1W1,W2W2,W0W1,W0W2,W1W2,W00W11
     & ,W00W22,W11W22,WW,QRAUX,MM,MLO,MDI,IKWPK,WORKS,WORKSS,WPK,VPK,
     & VWRI,WMAP,MULTMAP,JPVT,WSIZ,WRANK
      DOUBLE PRECISION FS(6),UDOT(6),TAUC(6),DYAD(3,3,3),FC(6,3),TC(6,3)
      DOUBLE PRECISION ANK(6,3),ONK(6,3),ONKB(6,3),AONKRI(6,3),ANKB(6,3)
     & ,ANKATK(6,3),ANB(3,3),ONB(3,3),DYRCOM(3,3)
      DOUBLE PRECISION FFK(6,3),TTK(6,3),FCCIKT(6,3),FFKB(3,3),TTKB(3,3)
      COMMON/SDGRHS/ FS,UDOT,ANK,ANB,ONK,ONB,ONKB,AONKRI,ANKB,ANKATK,
     & DYRCOM,FFK,TTK,FCCIKT,FFKB,TTKB,DYAD,FC,TC,TAUC
      DOUBLE PRECISION TEMP(3000),TMAT1(3,3),TMAT2(3,3),TVEC1(3),TVEC2(3
     & ),TVEC3(3),TVEC4(3),TVEC5(3)
      DOUBLE PRECISION TSC1,TSC2,TSC3
      COMMON/SDGTEMP/ TEMP,TMAT1,TMAT2,TVEC1,TVEC2,TVEC3,TVEC4,TVEC5,
     & TSC1,TSC2,TSC3
C
C
C Compute hinge torques for tree hinges
C
      TAUC(1)= (MTAU(1)+UTAU(1))
      TAUC(2)= (MTAU(2)+UTAU(2))
      TAUC(3)= (MTAU(3)+UTAU(3))
      TAUC(4)= (MTAU(4)+UTAU(4))
      TAUC(5)= (MTAU(5)+UTAU(5))
      TAUC(6)= (MTAU(6)+UTAU(6))
      CALL SDDOINER
C
C Compute onk & onb (angular accels in N)
C
      ONKB(2,2)= (UDOT(1)*C2)
      ONKB(2,3)= -(UDOT(1)*S2)
      ONKB(4,1)= (UDOT(4)+((CIK(4,3,1)*ONKB(2,3))+((CIK(4,1,1)*UDOT(2))+
     & (CIK(4,2,1)*ONKB(2,2)))))
      ONKB(4,2)= ((CIK(4,3,2)*ONKB(2,3))+((CIK(4,1,2)*UDOT(2))+(
     & CIK(4,2,2)*ONKB(2,2))))
      ONKB(4,3)= ((CIK(4,3,3)*ONKB(2,3))+((CIK(4,1,3)*UDOT(2))+(
     & CIK(4,2,3)*ONKB(2,2))))
      ONKB(5,2)= (ONKB(4,2)+UDOT(5))
      ONKB(6,3)= (ONKB(4,3)+UDOT(6))
      ONK(2,2)= (ONKB(2,2)+OTK(2,2))
      ONK(2,3)= (ONKB(2,3)+OTK(2,3))
      ONK(3,2)= (ONKB(2,2)+OTK(2,2))
      ONK(3,3)= (ONKB(2,3)+OTK(2,3))
      ONK(6,1)= (ONKB(4,1)+OTK(6,1))
      ONK(6,2)= (ONKB(5,2)+OTK(6,2))
      ONK(6,3)= (ONKB(6,3)+OTK(6,3))
      ONB(1,1)= UDOT(2)
      ONB(1,2)= ONK(2,2)
      ONB(1,3)= ONK(2,3)
      ONB(2,1)= UDOT(2)
      ONB(2,2)= ONK(3,2)
      ONB(2,3)= ONK(3,3)
      ONB(3,1)= ONK(6,1)
      ONB(3,2)= ONK(6,2)
      ONB(3,3)= ONK(6,3)
C
C Compute acceleration dyadics
C
      DYAD(1,1,1)= W11W22(1)
      DYAD(1,1,2)= (W0W1(1)-ONK(2,3))
      DYAD(1,1,3)= (ONK(2,2)+W0W2(1))
      DYAD(1,2,1)= (ONK(2,3)+W0W1(1))
      DYAD(1,2,2)= W00W22(1)
      DYAD(1,2,3)= (W1W2(1)-UDOT(2))
      DYAD(1,3,1)= (W0W2(1)-ONK(2,2))
      DYAD(1,3,2)= (UDOT(2)+W1W2(1))
      DYAD(1,3,3)= W00W11(1)
      DYAD(2,1,1)= W11W22(2)
      DYAD(2,1,2)= (W0W1(2)-ONK(3,3))
      DYAD(2,1,3)= (ONK(3,2)+W0W2(2))
      DYAD(2,2,1)= (ONK(3,3)+W0W1(2))
      DYAD(2,2,2)= W00W22(2)
      DYAD(2,2,3)= (W1W2(2)-UDOT(2))
      DYAD(2,3,1)= (W0W2(2)-ONK(3,2))
      DYAD(2,3,2)= (UDOT(2)+W1W2(2))
      DYAD(2,3,3)= W00W11(2)
      DYAD(3,1,1)= W11W22(3)
      DYAD(3,1,2)= (W0W1(3)-ONK(6,3))
      DYAD(3,1,3)= (ONK(6,2)+W0W2(3))
      DYAD(3,2,1)= (ONK(6,3)+W0W1(3))
      DYAD(3,2,2)= W00W22(3)
      DYAD(3,2,3)= (W1W2(3)-ONK(6,1))
      DYAD(3,3,1)= (W0W2(3)-ONK(6,2))
      DYAD(3,3,2)= (ONK(6,1)+W1W2(3))
      DYAD(3,3,3)= W00W11(3)
C
C Compute ank & anb (mass center linear accels in N)
C
      ANKB(3,1)= -(ONKB(2,3)*Q(3))
      ANKB(3,3)= (Q(3)*UDOT(2))
      ANKB(4,1)= ((ANKB(3,3)*CIK(4,3,1))+((ANKB(3,1)*CIK(4,1,1))+(
     & CIK(4,2,1)*UDOT(3))))
      ANKB(4,2)= ((ANKB(3,3)*CIK(4,3,2))+((ANKB(3,1)*CIK(4,1,2))+(
     & CIK(4,2,2)*UDOT(3))))
      ANKB(4,3)= ((ANKB(3,3)*CIK(4,3,3))+((ANKB(3,1)*CIK(4,1,3))+(
     & CIK(4,2,3)*UDOT(3))))
      ANKATK(3,1)= (ANKB(3,1)+ATK(3,1))
      ANKATK(3,2)= (ATK(3,2)+UDOT(3))
      ANKATK(3,3)= (ANKB(3,3)+ATK(3,3))
      ANK(3,1)= ((ANKATK(3,3)*CNK(2,1,3))+((ANKATK(3,1)*C1)+(ANKATK(3,2)
     & *CNK(2,1,2))))
      ANK(3,2)= ((ANKATK(3,2)*C2)-(ANKATK(3,3)*S2))
      ANK(3,3)= ((ANKATK(3,3)*CNK(2,3,3))+((ANKATK(3,2)*CNK(2,3,2))-(
     & ANKATK(3,1)*S1)))
      ANKATK(6,1)= (ANKB(4,1)+ATK(4,1))
      ANKATK(6,2)= (ANKB(4,2)+ATK(4,2))
      ANKATK(6,3)= (ANKB(4,3)+ATK(4,3))
      ANK(6,1)= ((ANKATK(6,3)*CNK(4,1,3))+((ANKATK(6,1)*CNK(4,1,1))+(
     & ANKATK(6,2)*CNK(4,1,2))))
      ANK(6,2)= ((ANKATK(6,3)*CNK(4,2,3))+((ANKATK(6,1)*CNK(4,2,1))+(
     & ANKATK(6,2)*CNK(4,2,2))))
      ANK(6,3)= ((ANKATK(6,3)*CNK(4,3,3))+((ANKATK(6,1)*CNK(4,3,1))+(
     & ANKATK(6,2)*CNK(4,3,2))))
      ANB(1,1)= 0D0
      ANB(1,2)= 0D0
      ANB(1,3)= 0D0
      ANB(2,1)= ANK(3,1)
      ANB(2,2)= ANK(3,2)
      ANB(2,3)= ANK(3,3)
      ANB(3,1)= ANK(6,1)
      ANB(3,2)= ANK(6,2)
      ANB(3,3)= ANK(6,3)
C
C Compute constraint acceleration errors
C
      ROUSTATE= 3
      CALL SDUAERR(CURTIM,Q,U,UDOT,AERR(2))
C
C  Used 0.00 seconds CPU time,
C  0 additional bytes of memory.
C  Equations contain   65 adds/subtracts/negates
C                      39 multiplies
C                       0 divides
C                      82 assignments
C
C
      RETURN
      END
C
      SUBROUTINE SDMASSMAT(MMAT)
      DOUBLE PRECISION MMAT(6,6)
C
C Return the system mass matrix (LHS)
C
      DOUBLE PRECISION GRAV(3),MK(3),IK(3,3,3),PIN(6,3)
      DOUBLE PRECISION RK(3,3),RI(3,3),PRES(6),STABVEL,STABPOS
      INTEGER MFRCFLG,ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,
     & LTAUFLG,FS0FLG,II,MMAP(6)
      INTEGER GRAVQ(3),MKQ(3),IKQ(3,3,3),PINQ(6,3),RKQ(3,3),RIQ(3,3),
     & PRESQ(6),STABVELQ,STABPOSQ
      DOUBLE PRECISION MTOT,PSMKG,RHEAD(3,3),RCOM(3,3),MKRCOMT(3,3,3),
     & PSIKG(3,3),PSRCOMG(3),PSRKG(3),PSRIG(3),PSMK(6),PSIK(6,3,3),
     & PSRCOM(6,3),PSRK(6,3),PSRI(6,3)
      COMMON/SDGINPUT/ GRAV,MK,IK,PIN,RK,RI,PRES,STABVEL,STABPOS,RHEAD,
     & RCOM,PSRCOMG,PSRCOM,MKRCOMT,PSMK,PSIK,PSRK,PSRI,PSMKG,PSIKG,PSRKG
     & ,PSRIG,MTOT,MFRCFLG,ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,
     & LTAUFLG,FS0FLG,II,MMAP,GRAVQ,MKQ,IKQ,PINQ,RKQ,RIQ,PRESQ,STABVELQ,
     & STABPOSQ
      DOUBLE PRECISION FS0(6),QDOT(7),OTK(6,3),ATK(6,3),AIOIWI(6,3),
     & FSTAR(6,3)
      DOUBLE PRECISION TSTAR(6,3),FSTARK(6,3),TSTARK(6,3),IKWK(6,3),
     & WKIKWK(6,3),GK(6,3),IKBWK(3,3),WKIKBWK(3,3)
      DOUBLE PRECISION W0W0(3),W1W1(3),W2W2(3),W0W1(3),W0W2(3),W1W2(3)
      DOUBLE PRECISION W00W11(3),W00W22(3),W11W22(3),WW(3,3),QRAUX(3)
      DOUBLE PRECISION MM(6,6),MLO(6,6),MDI(6),IKWPK(6,6,3),WORKS(6),
     & WORKSS(6,6)
      DOUBLE PRECISION WPK(6,6,3),VPK(6,6,3),VWRI(6,6,3)
      INTEGER WMAP(3),MULTMAP(3),JPVT(3),WSIZ,WRANK
      COMMON/SDGLHS/ QDOT,OTK,ATK,AIOIWI,FSTAR,TSTAR,FS0,FSTARK,TSTARK,
     & IKWK,IKBWK,WKIKWK,WKIKBWK,GK,W0W0,W1W1,W2W2,W0W1,W0W2,W1W2,W00W11
     & ,W00W22,W11W22,WW,QRAUX,MM,MLO,MDI,IKWPK,WORKS,WORKSS,WPK,VPK,
     & VWRI,WMAP,MULTMAP,JPVT,WSIZ,WRANK
      INTEGER I,J
C
      IF ((ROUSTATE .NE. 2) .AND. (ROUSTATE .NE. 3)) THEN
        CALL SDSETERR(57,23)
        RETURN
      ENDIF
      CALL SDDOMM(57)
      DO 110 I=1,6
        DO 100 J=I,6
          MMAT(I,J)= MM(I,J)
          MMAT(J,I)= MM(I,J)
100     CONTINUE
110   CONTINUE
C
      RETURN
      END
C
      SUBROUTINE SDFRCMAT(FMAT)
      DOUBLE PRECISION FMAT(6)
C
C Return the system force matrix (RHS), excluding constraints
C
      DOUBLE PRECISION GRAV(3),MK(3),IK(3,3,3),PIN(6,3)
      DOUBLE PRECISION RK(3,3),RI(3,3),PRES(6),STABVEL,STABPOS
      INTEGER MFRCFLG,ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,
     & LTAUFLG,FS0FLG,II,MMAP(6)
      INTEGER GRAVQ(3),MKQ(3),IKQ(3,3,3),PINQ(6,3),RKQ(3,3),RIQ(3,3),
     & PRESQ(6),STABVELQ,STABPOSQ
      DOUBLE PRECISION MTOT,PSMKG,RHEAD(3,3),RCOM(3,3),MKRCOMT(3,3,3),
     & PSIKG(3,3),PSRCOMG(3),PSRKG(3),PSRIG(3),PSMK(6),PSIK(6,3,3),
     & PSRCOM(6,3),PSRK(6,3),PSRI(6,3)
      COMMON/SDGINPUT/ GRAV,MK,IK,PIN,RK,RI,PRES,STABVEL,STABPOS,RHEAD,
     & RCOM,PSRCOMG,PSRCOM,MKRCOMT,PSMK,PSIK,PSRK,PSRI,PSMKG,PSIKG,PSRKG
     & ,PSRIG,MTOT,MFRCFLG,ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,
     & LTAUFLG,FS0FLG,II,MMAP,GRAVQ,MKQ,IKQ,PINQ,RKQ,RIQ,PRESQ,STABVELQ,
     & STABPOSQ
      DOUBLE PRECISION FS0(6),QDOT(7),OTK(6,3),ATK(6,3),AIOIWI(6,3),
     & FSTAR(6,3)
      DOUBLE PRECISION TSTAR(6,3),FSTARK(6,3),TSTARK(6,3),IKWK(6,3),
     & WKIKWK(6,3),GK(6,3),IKBWK(3,3),WKIKBWK(3,3)
      DOUBLE PRECISION W0W0(3),W1W1(3),W2W2(3),W0W1(3),W0W2(3),W1W2(3)
      DOUBLE PRECISION W00W11(3),W00W22(3),W11W22(3),WW(3,3),QRAUX(3)
      DOUBLE PRECISION MM(6,6),MLO(6,6),MDI(6),IKWPK(6,6,3),WORKS(6),
     & WORKSS(6,6)
      DOUBLE PRECISION WPK(6,6,3),VPK(6,6,3),VWRI(6,6,3)
      INTEGER WMAP(3),MULTMAP(3),JPVT(3),WSIZ,WRANK
      COMMON/SDGLHS/ QDOT,OTK,ATK,AIOIWI,FSTAR,TSTAR,FS0,FSTARK,TSTARK,
     & IKWK,IKBWK,WKIKWK,WKIKBWK,GK,W0W0,W1W1,W2W2,W0W1,W0W2,W1W2,W00W11
     & ,W00W22,W11W22,WW,QRAUX,MM,MLO,MDI,IKWPK,WORKS,WORKSS,WPK,VPK,
     & VWRI,WMAP,MULTMAP,JPVT,WSIZ,WRANK
      INTEGER I
C
      IF ((ROUSTATE .NE. 2) .AND. (ROUSTATE .NE. 3)) THEN
        CALL SDSETERR(58,23)
        RETURN
      ENDIF
      CALL SDDOFS0
      DO 100 I=1,6
        FMAT(I)= FS0(I)
100   CONTINUE
C
      RETURN
      END
