      DOUBLE PRECISION WKK(6,3),VKK(6,3),DIK(6,3),RPP(6,3),RPK(6,3),RIK(
     & 6,3),RIK2(6,3)
      DOUBLE PRECISION RPRI(6,3),WIK(6,3),VIK(6,3),WIRK(6,3),RKWKK(6,3),
     & WKRPK(6,3),VIKWKR(6,3)
      DOUBLE PRECISION PERR(3),VERR(3),AERR(3),MULT(3),UFK(3,3),UTK(3,3)
     & ,MFK(3,3),MTK(3,3)
      DOUBLE PRECISION UTAU(6),MTAU(6),UACC(6),UVEL(6),UPOS(7)
      DOUBLE PRECISION S1,C1,S2,C2
      COMMON/SDGSTATE/ CURTIM,Q,QN,U,CNK,CNB,RNKG,RNK,RNB,VNK,VNB,WK,WB,
     & COM,CIK,CIB,RIKT,IKO,MKRK,WKK,VKK,DIK,RPP,RPK,RIK,RIK2,RPRI,WIK,
     & VIK,WIRK,RKWKK,WKRPK,VIKWKR,WBRCOM,PERR,VERR,AERR,MULT,UFK,UTK,
     & UTAU,MFK,MTK,MTAU,UACC,UVEL,UPOS,S1,C1,S2,C2
      DOUBLE PRECISION FS0(6),QDOT(7),OTK(6,3),ATK(6,3),AIOIWI(6,3),
     & FSTAR(6,3)
      DOUBLE PRECISION TSTAR(6,3),FSTARK(6,3),TSTARK(6,3),IKWK(6,3),
     & WKIKWK(6,3),GK(6,3),IKBWK(3,3),WKIKBWK(3,3)
      DOUBLE PRECISION W0W0(3),W1W1(3),W2W2(3),W0W1(3),W0W2(3),W1W2(3)
      DOUBLE PRECISION W00W11(3),W00W22(3),W11W22(3),WW(3,3),QRAUX(3)
      DOUBLE PRECISION MM(6,6),MLO(6,6),MDI(6),IKWPK(6,6,3),WORKS(6),
     & WORKSS(6,6)
      DOUBLE PRECISION WPK(6,6,3),VPK(6,6,3),VWRI(6,6,3)
      INTEGER WMAP(3),MULTMAP(3),JPVT(3),WSIZ,WRANK
      COMMON/SDGLHS/ QDOT,OTK,ATK,AIOIWI,FSTAR,TSTAR,FS0,FSTARK,TSTARK,
     & IKWK,IKBWK,WKIKWK,WKIKBWK,GK,W0W0,W1W1,W2W2,W0W1,W0W2,W1W2,W00W11
     & ,W00W22,W11W22,WW,QRAUX,MM,MLO,MDI,IKWPK,WORKS,WORKSS,WPK,VPK,
     & VWRI,WMAP,MULTMAP,JPVT,WSIZ,WRANK
      DOUBLE PRECISION FS(6),UDOT(6),TAUC(6),DYAD(3,3,3),FC(6,3),TC(6,3)
      DOUBLE PRECISION ANK(6,3),ONK(6,3),ONKB(6,3),AONKRI(6,3),ANKB(6,3)
     & ,ANKATK(6,3),ANB(3,3),ONB(3,3),DYRCOM(3,3)
      DOUBLE PRECISION FFK(6,3),TTK(6,3),FCCIKT(6,3),FFKB(3,3),TTKB(3,3)
      COMMON/SDGRHS/ FS,UDOT,ANK,ANB,ONK,ONB,ONKB,AONKRI,ANKB,ANKATK,
     & DYRCOM,FFK,TTK,FCCIKT,FFKB,TTKB,DYAD,FC,TC,TAUC
      DOUBLE PRECISION TEMP(3000),TMAT1(3,3),TMAT2(3,3),TVEC1(3),TVEC2(3
     & ),TVEC3(3),TVEC4(3),TVEC5(3)
      DOUBLE PRECISION TSC1,TSC2,TSC3
      COMMON/SDGTEMP/ TEMP,TMAT1,TMAT2,TVEC1,TVEC2,TVEC3,TVEC4,TVEC5,
     & TSC1,TSC2,TSC3
      DOUBLE PRECISION PP(3,6),DPP(6,3)
      INTEGER I,J,C
      DOUBLE PRECISION SUM
      DOUBLE PRECISION DFK(3,3),DTK(3,3),DTAU(6),DLTCI(1,3),DLTC(1,3),
     & DLFCI(1,3),DLFC(1,3)
      DOUBLE PRECISION DTINB(1,3),DTOUTB(1,3),DLTAUFI(1,3),DLTAUFO(1,3),
     & DLTAUTI(1,3),DLTAUTO(1,3)
      DOUBLE PRECISION UMULT(2)
      DOUBLE PRECISION DFS(6),ROW(6),DINVROW(6)
C
      ROUSTATE= 2
      IF (WWFLG .EQ. 0) THEN
C
C Compute constraint effects
C
        CALL SDDOVPK
        CALL SDDOMMLDU(ROUTINE)
C
C Constraint 1 (prescribed motion)
C
        IF (PRES(3)  .NE.  0D0) THEN
          DTAU(3)= 1D0
        ELSE
          DTAU(3)= 0D0
        ENDIF
        DFS(3)= DTAU(3)
        DFS(1)= 0D0
        DFS(2)= 0D0
        DFS(4)= 0D0
        DFS(5)= 0D0
        DFS(6)= 0D0
        CALL SDLDUBSL(6,6,MMAP,MLO,DFS,ROW)
        CALL SDLDUBSD(6,6,MMAP,MDI,ROW,DINVROW)
        DO 100 I=1,6
          PP(1,I)= ROW(I)
          DPP(I,1)= DINVROW(I)
100     CONTINUE
        WMAP(1)= 1
C
C Constraint 2 (user constraint)
C
C
C Initialize all multiplier forces to zero.
C
        DO 102 I=1,3
          DO 101 J=1,3
            MFK(I,J)= 0D0
            MTK(I,J)= 0D0
101       CONTINUE
102     CONTINUE
        DO 103 I=1,6
          MTAU(I)= 0D0
103     CONTINUE
C
C Compute user-generated multiplier forces
C
        UMULT(1)= 1D0
        UMULT(2)= 0D0
        MFRCFLG= 1
        CALL SDUCONSFRC(CURTIM,Q,U,UMULT)
        MFRCFLG= 0
        CALL SDFSMULT
        CALL SDLDUBSL(6,6,MMAP,MLO,FS,ROW)
        CALL SDLDUBSD(6,6,MMAP,MDI,ROW,DINVROW)
        DO 104 I=1,6
          PP(2,I)= ROW(I)
          DPP(I,2)= DINVROW(I)
104     CONTINUE
        WMAP(2)= 2
C
C Constraint 3 (user constraint)
C
C
C Initialize all multiplier forces to zero.
C
        DO 106 I=1,3
          DO 105 J=1,3
            MFK(I,J)= 0D0
            MTK(I,J)= 0D0
105       CONTINUE
106     CONTINUE
        DO 107 I=1,6
          MTAU(I)= 0D0
107     CONTINUE
C
C Compute user-generated multiplier forces
C
        UMULT(1)= 0D0
        UMULT(2)= 1D0
        MFRCFLG= 1
        CALL SDUCONSFRC(CURTIM,Q,U,UMULT)
        MFRCFLG= 0
        CALL SDFSMULT
        CALL SDLDUBSL(6,6,MMAP,MLO,FS,ROW)
        CALL SDLDUBSD(6,6,MMAP,MDI,ROW,DINVROW)
        DO 108 I=1,6
          PP(3,I)= ROW(I)
          DPP(I,3)= DINVROW(I)
108     CONTINUE
        WMAP(3)= 3
C
C Produce constraint coefficient matrix WW
C
        DO 111 C=1,3
          DO 110 I=C,3
            SUM= 0D0
            DO 109 J=1,6
              SUM= SUM+PP(WMAP(C),J)*DPP(J,WMAP(I))
109         CONTINUE
            WW(WMAP(C),WMAP(I))= SUM
            WW(WMAP(I),WMAP(C))= SUM
110       CONTINUE
111     CONTINUE
C
C Form QR decomposition of WW
C
        CALL SDQRDCOMP(3,3,3,3,WMAP,WMAP,WW,QRAUX,JPVT)
        WWFLG= 1
      ENDIF
C
C  Used 0.00 seconds CPU time,
C  0 additional bytes of memory.
C  Equations contain   36 adds/subtracts/negates
C                      36 multiplies
C                       0 divides
C                     150 assignments
C
C
      RETURN
      END
C
      SUBROUTINE SDXUDOT0(ROUTINE,OUDOT0)
      INTEGER ROUTINE
      DOUBLE PRECISION OUDOT0(6)
C
C
C Compute unconstrained equations
C
