C
      SUBROUTINE SDDERIV(OQDOT,OUDOT)
      DOUBLE PRECISION OQDOT(7),OUDOT(6)
C
C
C This is the derivative section for a 3-body ground-based
C system with 6 hinge degree(s) of freedom.
C 1 of the degrees of freedom may follow prescribed motion.
C There are 3 constraints.
C
      DOUBLE PRECISION GRAV(3),MK(3),IK(3,3,3),PIN(6,3)
      DOUBLE PRECISION RK(3,3),RI(3,3),PRES(6),STABVEL,STABPOS
      INTEGER MFRCFLG,ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,
     & LTAUFLG,FS0FLG,II,MMAP(6)
      INTEGER GRAVQ(3),MKQ(3),IKQ(3,3,3),PINQ(6,3),RKQ(3,3),RIQ(3,3),
     & PRESQ(6),STABVELQ,STABPOSQ
      DOUBLE PRECISION MTOT,PSMKG,RHEAD(3,3),RCOM(3,3),MKRCOMT(3,3,3),
     & PSIKG(3,3),PSRCOMG(3),PSRKG(3),PSRIG(3),PSMK(6),PSIK(6,3,3),
     & PSRCOM(6,3),PSRK(6,3),PSRI(6,3)
      COMMON/SDGINPUT/ GRAV,MK,IK,PIN,RK,RI,PRES,STABVEL,STABPOS,RHEAD,
     & RCOM,PSRCOMG,PSRCOM,MKRCOMT,PSMK,PSIK,PSRK,PSRI,PSMKG,PSIKG,PSRKG
     & ,PSRIG,MTOT,MFRCFLG,ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,
     & LTAUFLG,FS0FLG,II,MMAP,GRAVQ,MKQ,IKQ,PINQ,RKQ,RIQ,PRESQ,STABVELQ,
     & STABPOSQ
      DOUBLE PRECISION CURTIM,Q(7),QN(7),U(6),CNK(6,3,3),CNB(3,3,3)
      DOUBLE PRECISION RNK(6,3),VNK(6,3),WK(6,3),RNB(3,3),VNB(3,3),WB(3,
     & 3),WBRCOM(3,3),COM(3),RNKG(3)
      DOUBLE PRECISION CIK(6,3,3),RIKT(6,3,3),IKO(6,3,3),MKRK(6,3,3),CIB
     & (3,3,3)
      DOUBLE PRECISION WKK(6,3),VKK(6,3),DIK(6,3),RPP(6,3),RPK(6,3),RIK(
     & 6,3),RIK2(6,3)
      DOUBLE PRECISION RPRI(6,3),WIK(6,3),VIK(6,3),WIRK(6,3),RKWKK(6,3),
     & WKRPK(6,3),VIKWKR(6,3)
      DOUBLE PRECISION PERR(3),VERR(3),AERR(3),MULT(3),UFK(3,3),UTK(3,3)
     & ,MFK(3,3),MTK(3,3)
      DOUBLE PRECISION UTAU(6),MTAU(6),UACC(6),UVEL(6),UPOS(7)
      DOUBLE PRECISION S1,C1,S2,C2
      COMMON/SDGSTATE/ CURTIM,Q,QN,U,CNK,CNB,RNKG,RNK,RNB,VNK,VNB,WK,WB,
     & COM,CIK,CIB,RIKT,IKO,MKRK,WKK,VKK,DIK,RPP,RPK,RIK,RIK2,RPRI,WIK,
     & VIK,WIRK,RKWKK,WKRPK,VIKWKR,WBRCOM,PERR,VERR,AERR,MULT,UFK,UTK,
     & UTAU,MFK,MTK,MTAU,UACC,UVEL,UPOS,S1,C1,S2,C2
      DOUBLE PRECISION FS0(6),QDOT(7),OTK(6,3),ATK(6,3),AIOIWI(6,3),
     & FSTAR(6,3)
      DOUBLE PRECISION TSTAR(6,3),FSTARK(6,3),TSTARK(6,3),IKWK(6,3),
     & WKIKWK(6,3),GK(6,3),IKBWK(3,3),WKIKBWK(3,3)
      DOUBLE PRECISION W0W0(3),W1W1(3),W2W2(3),W0W1(3),W0W2(3),W1W2(3)
      DOUBLE PRECISION W00W11(3),W00W22(3),W11W22(3),WW(3,3),QRAUX(3)
      DOUBLE PRECISION MM(6,6),MLO(6,6),MDI(6),IKWPK(6,6,3),WORKS(6),
     & WORKSS(6,6)
      DOUBLE PRECISION WPK(6,6,3),VPK(6,6,3),VWRI(6,6,3)
      INTEGER WMAP(3),MULTMAP(3),JPVT(3),WSIZ,WRANK
      COMMON/SDGLHS/ QDOT,OTK,ATK,AIOIWI,FSTAR,TSTAR,FS0,FSTARK,TSTARK,
     & IKWK,IKBWK,WKIKWK,WKIKBWK,GK,W0W0,W1W1,W2W2,W0W1,W0W2,W1W2,W00W11
     & ,W00W22,W11W22,WW,QRAUX,MM,MLO,MDI,IKWPK,WORKS,WORKSS,WPK,VPK,
     & VWRI,WMAP,MULTMAP,JPVT,WSIZ,WRANK
      DOUBLE PRECISION FS(6),UDOT(6),TAUC(6),DYAD(3,3,3),FC(6,3),TC(6,3)
      DOUBLE PRECISION ANK(6,3),ONK(6,3),ONKB(6,3),AONKRI(6,3),ANKB(6,3)
     & ,ANKATK(6,3),ANB(3,3),ONB(3,3),DYRCOM(3,3)
      DOUBLE PRECISION FFK(6,3),TTK(6,3),FCCIKT(6,3),FFKB(3,3),TTKB(3,3)
      COMMON/SDGRHS/ FS,UDOT,ANK,ANB,ONK,ONB,ONKB,AONKRI,ANKB,ANKATK,
     & DYRCOM,FFK,TTK,FCCIKT,FFKB,TTKB,DYAD,FC,TC,TAUC
      DOUBLE PRECISION WORKR(3),BB(3),B0(3),V0(3),P0(3)
      INTEGER IWORK(3)
      INTEGER I,J
      DOUBLE PRECISION UDOT0(6),UDOT1(6)
C
      IF ((ROUSTATE .NE. 2) .AND. (ROUSTATE .NE. 3)) THEN
        CALL SDSETERR(17,23)
        RETURN
      ENDIF
      IF (STABVELQ .EQ. 1) THEN
        CALL SDSETERR(17,32)
      ENDIF
      IF (STABPOSQ .EQ. 1) THEN
        CALL SDSETERR(17,33)
      ENDIF
      WSIZ= 3
C
C Compute unconstrained equations
C
      CALL SDXUDOT0(17,UDOT0)
      CALL SDRHS
      CALL SDAERR(B0)
      IF (STABVEL  .NE.  0D0) THEN
        CALL SDVERR(V0)
      ENDIF
      IF (STABPOS  .NE.  0D0) THEN
        CALL SDPERR(P0)
      ENDIF
C
C Stabilize constraints using Baumgarte's method
C
      DO 10 I=1,3
        BB(I)= -B0(I)
10    CONTINUE
      IF (STABVEL  .NE.  0D0) THEN
        DO 20 I=1,3
          BB(I)= BB(I)-STABVEL*V0(I)
20      CONTINUE
      ENDIF
      IF (STABPOS  .NE.  0D0) THEN
        DO 30 I=1,3
          BB(I)= BB(I)-STABPOS*P0(I)
30      CONTINUE
      ENDIF
C
C Compute and decompose constraint matrix WW
C
      CALL SDDOWW(17)
C
C Numerically solve for constraint multipliers
C
      CALL SDQRBSLV(3,3,3,3,WMAP,WMAP,1D-13,WORKR,IWORK,
     & WW,QRAUX,JPVT,BB,MULT,WRANK)
      DO 80 I=1,3
        MULTMAP(I)= 0
80    CONTINUE
      DO 85 I=1,WRANK
        MULTMAP(JPVT(I))= 1
85    CONTINUE
      J= 1
      DO 90 I=1,3
        IF (MULTMAP(I) .NE. 0) THEN
          MULTMAP(J)= WMAP(I)
          J= J+1
        ENDIF
90    CONTINUE
C
C Compute final udots
C
      CALL SDXUDOTM(17,MULT,UDOT1)
      DO 95 I=1,6
        UDOT(I)= UDOT0(I)+UDOT1(I)
95    CONTINUE
      CALL SDRHS
      DO 100 I=1,7
        OQDOT(I)= QDOT(I)
100   CONTINUE
      DO 110 I=1,6
        OUDOT(I)= UDOT(I)
110   CONTINUE
C
C  Used 0.00 seconds CPU time,
C  0 additional bytes of memory.
C  Equations contain   15 adds/subtracts/negates
C                       6 multiplies
C                       0 divides
C                      28 assignments
C
C
      RETURN
      END
C
C Compute residuals for use with DAE integrator
C
C
      SUBROUTINE SDRESID(EQDOT,EUDOT,EMULTS,RESID)
      DOUBLE PRECISION EQDOT(7),EUDOT(6),EMULTS(3),RESID(16)
