      TTKB(1,2)= (MTK(1,2)+UTK(1,2))
      TTKB(1,3)= (MTK(1,3)+UTK(1,3))
      TTKB(2,1)= (MTK(2,1)+UTK(2,1))
      TTKB(2,2)= (MTK(2,2)+UTK(2,2))
      TTKB(2,3)= (MTK(2,3)+UTK(2,3))
      TTKB(3,1)= (MTK(3,1)+UTK(3,1))
      TTKB(3,2)= (MTK(3,2)+UTK(3,2))
      TTKB(3,3)= (MTK(3,3)+UTK(3,3))
      FC(6,1)= ((ANKATK(6,1)-GK(4,1))-FFKB(3,1))
      FC(6,2)= ((ANKATK(6,2)-GK(4,2))-FFKB(3,2))
      FC(6,3)= ((ANKATK(6,3)-GK(4,3))-FFKB(3,3))
      TC(6,1)= ((.4D0*ONK(6,1))-TTKB(3,1))
      TC(6,2)= ((.4D0*ONK(6,2))-TTKB(3,2))
      TC(6,3)= ((.4D0*ONK(6,3))-TTKB(3,3))
      FCCIKT(6,1)= FC(6,1)
      FCCIKT(6,2)= FC(6,2)
      FCCIKT(6,3)= FC(6,3)
      FFK(5,1)= -FCCIKT(6,1)
      FFK(5,2)= -FCCIKT(6,2)
      FFK(5,3)= -FCCIKT(6,3)
      TTK(5,1)= -TC(6,1)
      TTK(5,2)= -TC(6,2)
      TTK(5,3)= -TC(6,3)
