      FFK(4,2)= -FCCIKT(5,2)
      FFK(4,3)= -FCCIKT(5,3)
      TTK(4,1)= -TC(5,1)
      TTK(4,2)= -TC(5,2)
      TTK(4,3)= -TC(5,3)
      FC(4,1)= -FFK(4,1)
      FC(4,2)= -FFK(4,2)
      FC(4,3)= -FFK(4,3)
      TC(4,1)= -TTK(4,1)
      TC(4,2)= -TTK(4,2)
      TC(4,3)= -TTK(4,3)
      FCCIKT(4,1)= ((CIK(4,1,3)*FC(4,3))+((CIK(4,1,1)*FC(4,1))+(
     & CIK(4,1,2)*FC(4,2))))
      FCCIKT(4,2)= ((CIK(4,2,3)*FC(4,3))+((CIK(4,2,1)*FC(4,1))+(
     & CIK(4,2,2)*FC(4,2))))
      FCCIKT(4,3)= ((CIK(4,3,3)*FC(4,3))+((CIK(4,3,1)*FC(4,1))+(
     & CIK(4,3,2)*FC(4,2))))
      FFK(3,1)= (FFKB(2,1)-FCCIKT(4,1))
      FFK(3,2)= (FFKB(2,2)-FCCIKT(4,2))
      FFK(3,3)= (FFKB(2,3)-FCCIKT(4,3))
      TTK(3,1)= (TTKB(2,1)-((CIK(4,1,3)*TC(4,3))+((CIK(4,1,1)*TC(4,1))+(
     & CIK(4,1,2)*TC(4,2)))))
      TTK(3,2)= (TTKB(2,2)-((CIK(4,2,3)*TC(4,3))+((CIK(4,2,1)*TC(4,1))+(
     & CIK(4,2,2)*TC(4,2)))))
      TTK(3,3)= (TTKB(2,3)-((CIK(4,3,3)*TC(4,3))+((CIK(4,3,1)*TC(4,1))+(
     & CIK(4,3,2)*TC(4,2)))))
      FC(3,1)= -FFK(3,1)
      FC(3,2)= -FFK(3,2)
      FC(3,3)= -FFK(3,3)
      TC(3,1)= -TTK(3,1)
      TC(3,2)= -TTK(3,2)
      TC(3,3)= -TTK(3,3)
      FCCIKT(3,1)= FC(3,1)
      FCCIKT(3,2)= FC(3,2)
      FCCIKT(3,3)= FC(3,3)
      FFK(2,1)= (FFKB(1,1)-FCCIKT(3,1))
      FFK(2,2)= (FFKB(1,2)-FCCIKT(3,2))
      FFK(2,3)= (FFKB(1,3)-FCCIKT(3,3))
      TTK(2,1)= (TTKB(1,1)-(TC(3,1)+(FCCIKT(3,3)*Q(3))))
      TTK(2,2)= (TTKB(1,2)-TC(3,2))
      TTK(2,3)= (TTKB(1,3)-(TC(3,3)-(FCCIKT(3,1)*Q(3))))
      FC(2,1)= -FFK(2,1)
      FC(2,2)= -FFK(2,2)
      FC(2,3)= -FFK(2,3)
      TC(2,1)= -TTK(2,1)
      TC(2,2)= -TTK(2,2)
      TC(2,3)= -TTK(2,3)
      FCCIKT(2,1)= FC(2,1)
      FCCIKT(2,2)= ((FC(2,2)*C2)-(FC(2,3)*S2))
      FCCIKT(2,3)= ((FC(2,2)*S2)+(FC(2,3)*C2))
      FFK(1,1)= -FCCIKT(2,1)
      FFK(1,2)= -FCCIKT(2,2)
      FFK(1,3)= -FCCIKT(2,3)
      TTK(1,1)= -TC(2,1)
      TTK(1,2)= -((TC(2,2)*C2)-(TC(2,3)*S2))
      TTK(1,3)= -((TC(2,2)*S2)+(TC(2,3)*C2))
      FC(1,1)= -FFK(1,1)
      FC(1,2)= -FFK(1,2)
      FC(1,3)= -FFK(1,3)
      TC(1,1)= -TTK(1,1)
      TC(1,2)= -TTK(1,2)
      TC(1,3)= -TTK(1,3)
      FORCE(1,1)= FC(2,1)
      TORQUE(1,1)= TC(2,1)
      FORCE(1,2)= FC(2,2)
      TORQUE(1,2)= TC(2,2)
      FORCE(1,3)= FC(2,3)
      TORQUE(1,3)= TC(2,3)
      FORCE(2,1)= FC(3,1)
      TORQUE(2,1)= TC(3,1)
      FORCE(2,2)= FC(3,2)
      TORQUE(2,2)= TC(3,2)
      FORCE(2,3)= FC(3,3)
      TORQUE(2,3)= TC(3,3)
      FORCE(3,1)= FC(6,1)
      TORQUE(3,1)= TC(6,1)
      FORCE(3,2)= FC(6,2)
      TORQUE(3,2)= TC(6,2)
      FORCE(3,3)= FC(6,3)
      TORQUE(3,3)= TC(6,3)
C
C Compute reaction forces for tree weld joints
C
C
C  Used 0.00 seconds CPU time,
C  0 additional bytes of memory.
C  Equations contain  105 adds/subtracts/negates
C                      31 multiplies
C                       0 divides
