      IF ((ROUSTATE .NE. 2) .AND. (ROUSTATE .NE. 3)) THEN
        CALL SDSETERR(19,23)
        RETURN
      ENDIF
      LM(1)= VNK(3,1)
      LM(2)= VNK(3,2)
      LM(3)= VNK(3,3)
      AM(1)= (.4D0*((CNK(4,1,3)*WK(6,3))+((CNK(4,1,1)*WK(4,1))+(
     & CNK(4,1,2)*WK(5,2)))))
      AM(2)= (.4D0*((CNK(4,2,3)*WK(6,3))+((CNK(4,2,1)*WK(4,1))+(
     & CNK(4,2,2)*WK(5,2)))))
