     & CNK(4,3,2)*WK(5,2)))))
      KE= (.5D0*((.4D0*((WK(6,3)*WK(6,3))+((WK(4,1)*WK(4,1))+(WK(5,2)*
     & WK(5,2)))))+((VNK(3,3)*VNK(3,3))+((VNK(3,1)*VNK(3,1))+(VNK(3,2)*
     & VNK(3,2))))))
C
