     & RNK(3,3))))-((RNK(3,2)*RNK(3,2))+(RNK(3,3)*RNK(3,3))))
      ICM(1,2)= ((RNK(3,1)*RNK(3,2))+((.4D0*((CNK(4,1,3)*CNK(4,2,3))+((
     & CNK(4,1,1)*CNK(4,2,1))+(CNK(4,1,2)*CNK(4,2,2)))))-(RNK(3,1)*
     & RNK(3,2))))
      ICM(1,3)= ((RNK(3,1)*RNK(3,3))+((.4D0*((CNK(4,1,3)*CNK(4,3,3))+((
     & CNK(4,1,1)*CNK(4,3,1))+(CNK(4,1,2)*CNK(4,3,2)))))-(RNK(3,1)*
     & RNK(3,3))))
      ICM(2,1)= ICM(1,2)
      ICM(2,2)= (((.4D0*((CNK(4,2,3)*CNK(4,2,3))+((CNK(4,2,1)*CNK(4,2,1)
     & )+(CNK(4,2,2)*CNK(4,2,2)))))+((RNK(3,1)*RNK(3,1))+(RNK(3,3)*
     & RNK(3,3))))-((RNK(3,1)*RNK(3,1))+(RNK(3,3)*RNK(3,3))))
      ICM(2,3)= ((RNK(3,2)*RNK(3,3))+((.4D0*((CNK(4,2,3)*CNK(4,3,3))+((
     & CNK(4,2,1)*CNK(4,3,1))+(CNK(4,2,2)*CNK(4,3,2)))))-(RNK(3,2)*
     & RNK(3,3))))
      ICM(3,1)= ICM(1,3)
      ICM(3,2)= ICM(2,3)
      ICM(3,3)= (((.4D0*((CNK(4,3,3)*CNK(4,3,3))+((CNK(4,3,1)*CNK(4,3,1)
     & )+(CNK(4,3,2)*CNK(4,3,2)))))+((RNK(3,1)*RNK(3,1))+(RNK(3,2)*
     & RNK(3,2))))-((RNK(3,1)*RNK(3,1))+(RNK(3,2)*RNK(3,2))))
C
C  Used 0.00 seconds CPU time,
C  0 additional bytes of memory.
C  Equations contain   30 adds/subtracts/negates
C                      42 multiplies
C                       0 divides
C                      13 assignments
C
C
      RETURN
      END
