        RETURN
      ENDIF
      IF (BODY .EQ. 0) THEN
        CALL SDSETERR(3,15)
        RETURN
      ENDIF
      ANYQUES= 0
      IF (IKQ(BODY,1,1)  .NE.  0) THEN
        IK(BODY,1,1)= INERIN(1,1)
        IKQ(BODY,1,1)= 3
        ANYQUES= 1
