      SUBROUTINE SDINFO(INFO)
      INTEGER INFO(50)
C
      INTEGER GROUND,NBOD,NDOF,NCONS,NLOOP,NLDOF,NLOOPC,NBALL,NLBALL,
     & NPRES,NUSER
      INTEGER JTYPE(3),INB(3),OUTB(3),NJNTDOF(3),NJNTC(3),NJNTP(3),
     & FIRSTQ(3),BALLQ(3),FIRSTM(3),FIRSTP(3)
      INTEGER TRANS(6),FIRSTU(2)
      COMMON/SDGTOPO/ GROUND,NBOD,NDOF,NCONS,NLOOP,NLDOF,NLOOPC,NBALL,
     & NLBALL,NPRES,NUSER,JTYPE,INB,OUTB,NJNTDOF,NJNTC,NJNTP,FIRSTQ,
     & BALLQ,FIRSTM,FIRSTP,TRANS,FIRSTU
C
      INFO(1)= GROUND
      INFO(2)= NBOD
      INFO(3)= NDOF
      INFO(4)= NCONS
      INFO(5)= NLOOP
      INFO(6)= NLDOF
      INFO(7)= NLOOPC
      INFO(8)= NBALL
      INFO(9)= NLBALL
      INFO(10)= NPRES
      INFO(11)= NUSER
      INFO(12)= 3
C info entries from 13-50 are reserved
C
      RETURN
      END
C
      SUBROUTINE SDJNT(JOINT,INFO,TRAN)
      INTEGER JOINT,INFO(50),TRAN(6)
C
      INTEGER GROUND,NBOD,NDOF,NCONS,NLOOP,NLDOF,NLOOPC,NBALL,NLBALL,
     & NPRES,NUSER
      INTEGER JTYPE(3),INB(3),OUTB(3),NJNTDOF(3),NJNTC(3),NJNTP(3),
     & FIRSTQ(3),BALLQ(3),FIRSTM(3),FIRSTP(3)
      INTEGER TRANS(6),FIRSTU(2)
      COMMON/SDGTOPO/ GROUND,NBOD,NDOF,NCONS,NLOOP,NLDOF,NLOOPC,NBALL,
     & NLBALL,NPRES,NUSER,JTYPE,INB,OUTB,NJNTDOF,NJNTC,NJNTP,FIRSTQ,
     & BALLQ,FIRSTM,FIRSTP,TRANS,FIRSTU
      INTEGER I,OFFS
      INTEGER SDCHKJNUM
C
      IF (SDCHKJNUM(48,JOINT) .NE. 0) THEN
        RETURN
      ENDIF
      INFO(1)= JTYPE(JOINT)
      INFO(2)= 0
      OFFS= 0
      INFO(3)= INB(JOINT)
      INFO(4)= OUTB(JOINT)
      INFO(5)= NJNTDOF(JOINT)
      INFO(6)= NJNTC(JOINT)
      INFO(7)= NJNTP(JOINT)
      INFO(8)= FIRSTQ(JOINT)
      INFO(9)= BALLQ(JOINT)
      INFO(10)= FIRSTM(JOINT)
      INFO(11)= FIRSTP(JOINT)
C info entries from 12-50 are reserved
C
      DO 100 I=0,5
        IF (I  .LT.  NJNTDOF(JOINT)) THEN
          TRAN(I+1)= TRANS(OFFS+FIRSTQ(JOINT)+I)
        ELSE
          TRAN(I+1)= -1
        ENDIF
100   CONTINUE
C
      RETURN
      END
C
      SUBROUTINE SDCONS(CONSNO,INFO)
      INTEGER CONSNO,INFO(50)
C
      INTEGER GROUND,NBOD,NDOF,NCONS,NLOOP,NLDOF,NLOOPC,NBALL,NLBALL,
     & NPRES,NUSER
      INTEGER JTYPE(3),INB(3),OUTB(3),NJNTDOF(3),NJNTC(3),NJNTP(3),
     & FIRSTQ(3),BALLQ(3),FIRSTM(3),FIRSTP(3)
      INTEGER TRANS(6),FIRSTU(2)
      COMMON/SDGTOPO/ GROUND,NBOD,NDOF,NCONS,NLOOP,NLDOF,NLOOPC,NBALL,
     & NLBALL,NPRES,NUSER,JTYPE,INB,OUTB,NJNTDOF,NJNTC,NJNTP,FIRSTQ,
     & BALLQ,FIRSTM,FIRSTP,TRANS,FIRSTU
C
      INTEGER SDCHKUCNUM
      IF (SDCHKUCNUM(49,CONSNO) .NE. 0) THEN
        RETURN
      ENDIF
      INFO(1)= 1
      INFO(2)= FIRSTU(CONSNO)
C info entries from 3-50 are reserved
C
      RETURN
      END
C
      SUBROUTINE SDGENTIME(GENTM)
      INTEGER GENTM
C
C
      GENTM= TIMESTAMP
C
      RETURN
      END
